(window.TNQ=window.TNQ||[]).push({"terms":{"최적함수비":{"d":"다짐시험에서 건조단위중량이 최대가 되는 함수비입니다.","r":["다짐에너지"]},"다짐에너지":{"d":"흙을 다질 때 단위 부피에 가해지는 에너지입니다.","r":["최적함수비"]},"펠레니우스":{"d":"절편 양쪽 힘의 합력을 0으로 놓고 사면 안정을 계산하는 방법입니다.","r":[]},"비숍 간편법":{"d":"절편의 연직 합력을 0으로 놓고 시행착오로 사면 안정을 푸는 방법입니다.","r":[]},"배합강도":{"d":"콘크리트 품질 변동을 감안해 설계기준강도보다 크게 잡는 목표 강도입니다.","r":[]},"과잉간극수압":{"d":"하중 때문에 간극수에 더해진 압력으로 압밀이 진행되며 사라집니다.","r":["피에조미터"]},"피에조미터":{"d":"흙 속의 간극수압을 수위나 압력으로 재는 기구입니다.","r":["과잉간극수압"]},"유효응력":{"d":"전응력에서 간극수압을 뺀 것으로 흙입자가 실제로 받는 응력입니다.","r":[]},"유선망":{"d":"유선과 등수두선을 그려 흙 속 침투수의 흐름을 나타낸 그림입니다.","r":[]},"프리텐션":{"d":"긴장재를 먼저 당긴 채 콘크리트를 쳐서 굳은 뒤 풀어 프리스트레스를 주는 방식입니다.","r":[]},"조강시멘트":{"d":"초기강도가 빠르게 올라가 거푸집을 일찍 뗄 수 있는 시멘트입니다.","r":[]},"고로시멘트":{"d":"포틀랜드시멘트 클링커에 고로슬래그를 섞은 혼합 시멘트로 장기강도가 높습니다.","r":[]},"알루미나시멘트":{"d":"보크사이트와 석회석으로 만들어 초기강도가 매우 큰 시멘트입니다.","r":[]},"평판재하시험":{"d":"재하판에 하중을 가해 지반의 지지력을 현장에서 재는 시험입니다.","r":[]},"트레미":{"d":"수중에 콘크리트를 칠 때 쓰는 연직 관입니다.","r":[]},"컨시스턴시":{"d":"주로 수량에 따라 달라지는 반죽의 묽고 된 정도입니다.","r":[]},"침입도":{"d":"표준 침이 아스팔트에 들어간 깊이로 굳기를 나타낸 값입니다.","r":["인화점"]},"인화점":{"d":"아스팔트 증기에 불꽃을 가까이 댔을 때 불이 붙는 가장 낮은 온도입니다.","r":["침입도"]},"소성변형":{"d":"하중을 없애도 돌아오지 않는 변형으로 아스팔트 포장에서는 바퀴자국으로 나타납니다.","r":[]},"동역학 공식":{"d":"말뚝을 박을 때의 타격 에너지로 지지력을 추정하는 공식입니다.","r":[]},"웰포인트":{"d":"지하수위를 낮추려고 흙 속에 가는 관을 박아 물을 뽑는 공법입니다.","r":["샌드드레인"]},"샌드드레인":{"d":"연약 지반에 모래 기둥을 박아 물이 빠지는 길을 만드는 지반 개량 공법입니다.","r":["페이퍼드레인","프리로딩"]},"페이퍼드레인":{"d":"모래 대신 종이 모양의 배수재를 박아 간극수를 빼는 지반 개량 공법입니다.","r":["샌드드레인"]},"프리로딩":{"d":"미리 흙을 쌓아 하중을 주어 지반 침하를 먼저 일으키는 개량 공법입니다.","r":["샌드드레인"]},"바이브로플로테이션":{"d":"진동과 물로 느슨한 모래 지반을 다지는 공법입니다.","r":[]},"중성화":{"d":"콘크리트 알칼리성이 탄산가스 때문에 떨어져 철근 부식을 쉽게 하는 현상입니다.","r":["페놀프탈레인"]},"페놀프탈레인":{"d":"알칼리에서는 붉게 변하여 콘크리트 중성화 깊이를 가리는 지시약입니다.","r":["중성화"]},"AE제":{"d":"콘크리트에 미세한 공기 기포를 고르게 만드는 혼화제입니다.","r":[]},"실적률":{"d":"골재를 채운 용기 부피 중 골재 알이 차지하는 부피의 비율입니다.","r":[]},"조립률":{"d":"체가름 결과로 구하는 골재 알 크기의 평균적인 지표입니다.","r":[]},"부마찰력":{"d":"주변 흙이 말뚝보다 더 가라앉으며 말뚝을 아래로 끌어당기는 마찰력입니다.","r":[]},"콜드조인트":{"d":"먼저 친 콘크리트가 굳은 뒤 이어 쳐서 생기는 불연속 이음면입니다.","r":[]},"알칼리골재반응":{"d":"시멘트의 알칼리와 반응성 골재가 반응해 콘크리트를 팽창시키는 현상입니다.","r":["포졸란"]},"포졸란":{"d":"자체 수경성은 없으나 수산화칼슘과 반응해 굳는 실리카질 혼화재입니다.","r":[]},"뇌관":{"d":"기폭약이나 첨장약을 관 속에 채워 폭약을 터뜨리는 기폭 장치입니다.","r":["도화선"]},"도화선":{"d":"흑색화약을 심약으로 감싸 불꽃을 전달하는 선입니다.","r":["뇌관"]},"연성":{"d":"인장력을 받아 가늘고 길게 늘어나는 성질입니다.","r":["취성"]},"취성":{"d":"거의 늘어나지 않고 작은 변형에도 부서지는 성질입니다.","r":["연성"]},"인성":{"d":"재료가 파괴될 때까지 에너지를 흡수하는 능력입니다.","r":[]},"크리프":{"d":"일정한 하중이 계속될 때 시간이 지나며 변형이 늘어나는 현상입니다.","r":[]},"숏크리트":{"d":"압축공기로 콘크리트를 뿜어 붙이는 시공법입니다.","r":["리바운드"]},"리바운드":{"d":"뿜어붙이기 때 숏크리트가 벽에 붙지 않고 튕겨 떨어지는 현상입니다.","r":["숏크리트"]},"분말도":{"d":"시멘트 입자의 가늘고 굵은 정도를 나타내는 지표입니다.","r":[]},"온도균열지수":{"d":"콘크리트 인장강도를 온도응력으로 나눈 값으로 균열 위험을 나타냅니다.","r":[]},"히빙":{"d":"굴착한 바닥면이 흙의 압력으로 위로 솟는 현상입니다.","r":[]},"균등계수":{"d":"D60을 D10으로 나눈 값으로 흙 입도의 고른 정도를 나타냅니다.","r":[]},"다일러턴시":{"d":"전단할 때 흙의 부피가 늘거나 줄어드는 현상입니다.","r":[]},"고성능감수제":{"d":"단위수량을 크게 줄여 고강도 콘크리트에 쓰는 감수제입니다.","r":[]},"모어 응력원":{"d":"한 점의 임의 평면 응력상태를 원으로 나타낸 도해입니다.","r":[]},"군지수":{"d":"AASHTO 분류에서 노상 재료 적합성을 숫자로 나타낸 값입니다.","r":[]},"반발경도법":{"d":"표면을 타격해 반발 정도로 콘크리트 강도를 추정하는 비파괴시험입니다.","r":[]},"RQD":{"d":"10cm 이상 코어의 비율 등으로 암반 상태를 숫자로 나타낸 지표입니다.","r":[]},"흑색화약":{"d":"황, 목탄, 초석의 미분말을 섞어 만든 화약입니다.","r":[]},"다르시 법칙":{"d":"흙 속 물의 유속이 동수경사에 비례한다는 침투 법칙입니다.","r":[]},"한계동수경사":{"d":"분사가 막 시작될 때의 동수경사입니다.","r":[]},"트래피커빌리티":{"d":"시공기계가 연약한 흙 위를 주행할 수 있는 정도입니다.","r":[]},"할선탄성계수":{"d":"응력-변형률 곡선의 원점과 한 점을 이은 직선 기울기로 구한 탄성계수입니다.","r":[]},"석리":{"d":"조암광물이 모인 상태에 따라 생기는 암석의 눈 모양입니다.","r":[]},"절리":{"d":"암석에 자연적으로 갈라져 있는 금입니다.","r":[]},"면모구조":{"d":"점토 입자가 서로 끝과 면이 붙어 엉긴 구조입니다.","r":[]}},"notes":{"(－)다일러턴시로 수축하며 (＋) 다일러턴시가 일어나지 않는다":"느슨한 모래는 (－)다일러턴시로 부피가 줄고 (＋) 다일러턴시는 일어나지 않습니다.","0.1μm 정도의 초미립자로 포졸란 반응을 하며 플라이애시 사용 시 공기량 확보에 AE제를 더 쓴다":"실리카퓸은 0.1μm 정도의 초미립자라 포졸란 반응을 하며, 플라이애시를 쓰면 AE제를 더 써서 공기량을 확보합니다.","0℃ 이하에서는 콘크리트가 높은 반발경도를 보이므로 내부가 완전히 녹은 뒤 시험한다":"얼어 있는 콘크리트는 반발경도가 크게 나오므로 속까지 녹은 다음 슈미트해머로 시험합니다.","1.5mm 체도 해당하지 않는다":"1.5mm 체도 조립률용 표준체에 해당하지 않습니다.","100g 침으로 25℃에서 5초간 관입한 깊이이며 0.1mm가 1이다":"침입도는 100g 침을 25℃에서 5초 동안 눌렀을 때 들어간 깊이이며 0.1mm가 1입니다.","100mm 이하, 50~80mm를 표준으로 한다":"유동화 때 슬럼프 증가량은 100mm 이하로 하며 50~80mm가 표준입니다.","105±5℃에서 일정 질량이 될 때까지 건조한 상태":"절대건조상태는 105±5℃에서 질량이 변하지 않을 때까지 말린 상태입니다.","13포 이하로 쌓고 마루바닥은 지면에서 띄워 습기를 막으며 3개월 이상 저장하면 재시험한다":"포대시멘트는 13포를 넘겨 쌓지 않고 마루를 지면에서 띄워 두며, 3개월 넘게 저장하면 시험을 다시 합니다.","150m3당 1회, 1회 시험결과는 공시체 3개 평균이다":"압축강도 검사는 150m3마다 한 번 하며 1회 결과는 공시체 3개의 평균입니다.","15회 1.16, 20회 1.08, 25회 1.03, 30회 1.0이다":"표준편차는 시험횟수가 적을수록 보정계수를 키워, 15회는 1.16, 20회는 1.08, 25회는 1.03, 30회는 1.0입니다.","1개소 진동시간은 5~15초이며 천천히 빼내 구멍이 남지 않게 한다":"한 곳에서 5~15초 진동하고 천천히 빼내야 구멍이 남지 않습니다.","1에 가까우면 유동 가능성이 크고 0에 가까우면 안정된 점토이다":"액성지수가 1에 가까우면 유동하기 쉽고 0에 가까우면 안정된 점토입니다.","1점시간 추정에 공비절감이 목적":"CPM은 시간을 한 점으로 추정하고 공비절감을 목적으로 합니다.","25mm 체는 포함되지 않는다":"25mm 체는 조립률 계산용 표준체에 들어 있지 않습니다.","2개 이상 생길 수 있고 반드시 1개인 것은 아니다":"주공정선은 2개 이상 생길 수 있어 반드시 하나라고 할 수 없습니다.","2층 이상 나눠 칠 때는 하층이 굳기 전에 상층을 치고, 블리딩수는 제거하고 친다":"두 층 이상으로 나눠 칠 때는 아래층이 굳기 전에 위층을 치며, 블리딩수는 걷어 내고 칩니다.","3등분점 바깥쪽에서 파괴되면 그 결과를 무효로 한다":"3등분점 바깥쪽에서 파괴되면 정상적인 휨 파괴가 아니라서 그 결과를 쓰지 않습니다.","3점시간 추정에 공기단축이 주목적":"PERT는 작업 시간을 낙관·정상·비관 3점으로 추정하며 공기단축을 주목적으로 합니다.","3점 시간추정으로 확률 계산을 하며 신규·비반복 사업에 쓴다":"PERT는 3점 시간추정으로 확률 계산을 하며 처음 하는 사업에 씁니다.","5mm체를 통과한 부분을 잔골재로 보고 정한다":"잔골재율을 정할 때는 5mm체를 통과한 부분을 잔골재로 봅니다.","AASHTO 콘크리트포장 설계 입력자료이다":"교통조건은 AASHTO 콘크리트포장 설계에 입력하는 자료입니다.","AE제·경화촉진제·방수제이며":"혼화제에는 AE제, 경화촉진제, 방수제가 있습니다.","AE제와 같은 계면활성작용으로 기포를 도입해 단위중량을 줄이고 단열성·내화성을 높인다":"기포제는 AE제처럼 계면활성작용으로 기포를 넣어 단위중량을 줄이고 단열성과 내화성을 높입니다.","BH·RGP·ONS 공법은 주열식이고 ICOS는 주열식이 아니다":"주열식 벽체에는 BH, RGP, ONS 공법이 들고 ICOS 공법은 거기에 속하지 않습니다.","C2S는 수화가 느리나 장기강도에 도움이 되고 C3A는 수화가 빠르며 수화열이 높다":"C2S는 천천히 반응해 장기강도에 보탬이 되고, C3A는 빠르게 반응해 열을 많이 냅니다.","C3A를 줄여 수화열을 낮추고, 강도시험은 결합력 발현 정도를 알기 위해 한다":"중용열시멘트는 C3A를 줄여 수화열을 낮추며, 강도시험은 결합력이 어느 정도 나오는지 보기 위해 합니다.","C3S·C2S·C3A·C4AF 4가지":"클링커의 주요 화합물은 C3S, C2S, C3A, C4AF 네 가지입니다.","C3S와 C2S가 시멘트 강도의 대부분을 지배한다":"시멘트 강도는 대부분 C3S와 C2S 두 광물이 좌우합니다.","C4AF는 수화가 늦고 화학 저항성이 크며 C3S는 조기강도를 크게 한다":"C3S는 조기강도를 키우고, C4AF는 반응이 늦은 대신 화학 저항성이 큽니다.","CBR시험·평판재하시험·마샬시험이다":"포장 두께는 CBR시험, 평판재하시험, 마샬시험으로 정합니다.","CO2 농도와 온도가 높을수록 빠르고 판정은 페놀프탈레인 1% 알코올 용액으로 한다":"CO2 농도와 온도가 높을수록 중성화가 빠르며 페놀프탈레인 1% 알코올 용액으로 부분을 구분합니다.","Engineering-News 공식은 정역학 공식이 아니다":"Engineering-News 공식은 타격 에너지를 쓰는 동역학 공식이어서 정역학 공식이 아닙니다.","GP는 입도 불량한 자갈, GC는 점토 섞인 자갈, SM은 실트 섞인 모래이다":"GP는 입도가 나쁜 자갈, GC는 점토가 섞인 자갈, SM은 실트가 섞인 모래를 나타냅니다.","H/D가 작을수록 강도가 크고 같은 형상이면 치수가 클수록 강도가 작다":"H/D가 작은 공시체일수록 강도가 크게 나오고, 형상이 같아도 치수가 클수록 강도는 작아집니다.","IL＝(W－Wp)/Ip이며 일반적으로 0~1 사이다":"액성지수 IL은 (W－Wp)를 Ip로 나눈 값으로 일반적으로 0~1 사이입니다.","NATM 공법에 많이 쓰며 좌우 조정이 가능하다":"NATM 공법에서 많이 쓰는 점보드릴은 좌우 조정도 할 수 있습니다.","Nc·Nq·Nr는 내부마찰각으로 정해지고 마찰계수가 아니다":"지지력계수 Nc, Nq, Nr는 흙의 내부마찰각에 따라 정해지는 값이지 마찰계수가 아닙니다.","N값으로 모래의 상대밀도와 점토의 연경도를 개략 추정한다":"N값에 경험식을 적용하면 모래는 상대밀도를, 점토는 연경도를 대략 짐작할 수 있습니다.","N값이 클수록 지반 강도가 크지만 흐트러지지 않은 시료는 얻을 수 없다":"N값이 클수록 지반이 단단하지만 시료를 휘저어 채취하므로 불교란 시료는 얻지 못합니다.","Pull-out(인발)법은 균열깊이 평가법이 아니다":"Pull-out(인발)법은 강도 추정에 쓰이며 균열깊이를 재는 방법이 아닙니다.","RQD값·탄성파속도·균열의 간격으로 판정한다":"암질은 RQD값, 탄성파속도, 균열의 간격으로 판정합니다.","S(Sample)는 사이클 단계가 아니다":"품질관리 사이클 단계에 S(Sample)는 들어 있지 않습니다.","T-법·Tc-To법·BS법이다":"균열깊이는 초음파로 T-법, Tc-To법, BS법으로 평가합니다.","Vicat 장치는 워커빌리티 시험이 아니고 단위수량을 늘리는 것은 좋은 방법이 아니다":"Vicat 장치는 응결을 재는 기구이고, 단위수량을 늘리면 오히려 재료분리와 강도 저하를 부릅니다.","n＝R/W이며 n＝1이면 표준장약이고 1보다 크면 과장약이다":"누두지수 n은 R을 W로 나눈 값으로, n이 1이면 표준장약, 1보다 크면 과장약입니다.","qult＝αcNc＋βγ1BNr＋γ2DfNq이며 α·β는 기초 형태에 따른 형상계수이다":"극한지지력은 점착, 근입깊이, 기초폭 세 항을 더한 식이며 α·β는 기초 모양에 따라 정해집니다.","±0.20 이상 변하면 배합을 수정하고 경제적으로는 굵은골재 최대치수를 크게 한다":"조립률이 ±0.20 이상 달라지면 배합을 고치고, 경제성을 위해 굵은골재 최대치수는 크게 잡습니다.","φ＝0인 점토에서 점착력은 일축압축강도의 1/2이다":"φ가 0인 점토에서는 점착력이 일축압축강도의 절반입니다.","√t법과 log t법으로 구한다":"압밀계수는 압밀 시간 곡선에서 √t법이나 log t법으로 구합니다.","가볍지만 장거리 운반에 불리하고 같은 배합에서 슬럼프가 크지 않다":"경량골재콘크리트는 가볍지만 장거리 운반에 불리하고, 같은 배합에서도 슬럼프가 크지 않습니다.","가열 속도가 빠르면 인화점이 떨어지고 2회 시험 차가 8℃를 넘으면 안 된다":"가열 속도가 빠르면 인화점이 낮게 나오고 두 번 시험한 값의 차가 8℃를 넘으면 안 됩니다.","가장자리에서 100mm 이상, 서로 30mm 이내로 근접하지 않으며 부재 두께는 100mm 이상이다":"슈미트해머 타격은 가장자리에서 100mm 넘게 떨어지고 타점끼리 30mm 이내로 붙지 않으며 부재 두께 100mm 이상에서 합니다.","각 유로의 침투량은 같고 인접 등수두선 사이의 수두감소량도 같다":"유로마다 침투량이 같고 이웃한 등수두선 사이의 수두감소량도 같게 그립니다.","간극비와 유효입경에 반비례한다":"모관상승고는 간극비와 유효입경에 반비례합니다.","간극수압을 빼서 유효응력을 구한다":"지하수위 아래에서는 전응력에서 간극수압을 빼야 흙입자가 실제로 받는 유효응력이 됩니다.","갈라지기 쉬운 면은 석목(돌눈)이고, 방향이 불규칙하게 작게 갈라지는 것은 벽개가 아니다":"석목(돌눈)은 갈라지기 쉬운 면을 가리키고, 불규칙하게 작게 갈라지는 것은 벽개가 아닙니다.","값이 싸고 취급·보관이 간편하며 흡수성이 크고 충격·가열로 폭발한다":"흑색화약은 값이 싸고 다루기 쉬우나 습기를 잘 빨아들이고 충격이나 열로 폭발합니다.","강도가 크지만 풍화하기 쉬워 실외 사용에 주의한다":"대리석은 강도가 크지만 풍화되기 쉬워 바깥에 쓸 때 조심합니다.","강도가 클수록, 단위용적중량이 클수록 탄성계수가 크다":"탄성계수는 강도가 높고 단위용적중량이 클수록 커집니다.","강도·내구성·수밀성·균열저항성·철근 보호 성능을 고려해 정한다":"배합 설계는 강도, 내구성, 수밀성, 균열저항성, 철근 보호 성능을 함께 고려해 정합니다.","강도·탄성계수·열전도율이 낮고 흡수율이 크다":"경량골재콘크리트는 강도, 탄성계수, 열전도율이 낮고 흡수율이 큽니다.","강섬유·유리섬유·탄소섬유이다":"무기계 섬유에는 강섬유, 유리섬유, 탄소섬유가 있습니다.","강성기초의 접지압은 기초 모서리에서 최대이다":"점토지반 위의 강성기초는 접지압이 기초 모서리에서 최대가 됩니다.","강자갈보다 유동성이 좋아지는 것은 아니며 입도는 대·소립이 적당히 혼합되어야 한다":"부순골재가 강자갈보다 유동성이 좋은 것은 아니며 입도는 큰 알과 작은 알이 적당히 섞여야 합니다.","강 제조법은 평로·전로·전기로이고 열처리는 풀림·불림·담금질·뜨임이며 구리＋아연은 황동이다":"강은 평로, 전로, 전기로로 만들고 열처리는 풀림, 불림, 담금질, 뜨임이며 구리와 아연의 합금이 황동입니다.","같은 강도에서 일반보다 탄성계수가 작다":"경량콘크리트는 같은 강도에서 일반 콘크리트보다 탄성계수가 작습니다.","같은 슬럼프에 필요한 단위수량이 줄어든다":"굵은골재 최대치수를 키우면 같은 슬럼프에 필요한 단위수량이 줄어듭니다.","개시점에서 종료점까지 가장 긴 경로이다":"주공정선은 시작점에서 끝점까지 걸리는 시간이 가장 긴 경로입니다.","거칠어지고 재료분리가 생기며 조립률이 ±0.20 이상 변하면 배합을 수정한다":"잔골재율이 너무 작으면 거칠고 재료분리가 생기며 조립률이 ±0.20 이상 변하면 배합을 수정합니다.","거푸집 양 측면 사이 최소거리 1/5, 철근 순간격 3/4, 무근콘크리트 부재 최소치수 1/4을 넘지 않는다":"굵은골재 최대치수는 거푸집 측면 간격의 1/5, 철근 순간격의 3/4, 무근 부재 최소치수의 1/4 이하여야 합니다.","거푸집을 일찍 떼고 한중공사에 적합하나 수화열이 커 큰 단면에는 부적당하다":"조강시멘트는 일찍 굳어 거푸집을 빨리 떼고 한중공사에 맞지만 열이 커 큰 단면에는 맞지 않습니다.","건조단위중량과 함수비의 관계이고 최대건조밀도 때의 함수비가 최적함수비이다":"다짐곡선은 함수비에 따른 건조단위중량을 그린 것으로, 최대건조밀도일 때의 함수비가 최적함수비입니다.","건조하면 비틀림이 방지되고 강도가 증가하며 도료·주입제 효과가 커진다":"목재를 건조하면 비틀림이 막히고 강도가 늘며 도료나 주입제의 효과도 커집니다.","결과는 φ가 0이고 c는 0이 아니다":"UU 결과로는 φ가 0이 되고 점착력 c만 남아 c는 0이 아닙니다.","결합수가 감소하면 수축 변형하며 강도는 절대건조일 때 최대이다":"결합수가 줄면 목재가 수축 변형하며 강도는 절대건조 상태에서 가장 큽니다.","경간에 동바리를 설치해 자중 하중을 지지한다":"FSM은 경간 전체에 동바리를 세워 거푸집과 콘크리트 자중을 지지하는 공법입니다.","경사하중계수와 형상계수도 포함된다":"메이어호프 지지력 공식은 경사하중계수와 형상계수도 포함합니다.","경화 때까지 물의 유동을 방지하고 굵은골재는 둥근 모양을 쓰며 잔골재율은 작게 하지 않는다":"굳을 때까지 물이 흐르지 못하게 막고, 굵은골재는 둥글게 쓰며 잔골재율은 작게 잡지 않습니다.","경화를 시작할 때까지 직사광선·바람에 의한 수분 증발을 막는다":"타설 후 경화가 시작될 때까지 직사광선과 바람에 수분이 날아가지 않게 막습니다.","경화 속도는 RC>MC>SC 순이고 가열해 쓰는 것은 아니며 양생은 휘발성 큰 용제일수록 짧다":"컷백의 경화 속도는 RC, MC, SC 순이고 가열해 쓰지 않으며 휘발성 큰 용제일수록 양생이 짧습니다.","경화 시까지 진동·충격과 직사광선·바람에 의한 증발을 막고 부재두께 80cm 이상은 매스콘크리트 양생에 따른다":"경화될 때까지 진동, 충격, 직사광선, 바람을 막고 부재두께 80cm 이상은 매스콘크리트 양생을 따릅니다.","경화콘크리트 강도 추정 비파괴시험은 반발경도법·초음파속도법·조합법이다":"경화콘크리트 강도는 반발경도법, 초음파속도법, 이를 합친 조합법의 비파괴시험으로 추정합니다.","계면활성작용으로 워커빌리티와 내동해성을 개선한다":"AE제는 계면활성작용으로 미세 기포를 만들어 워커빌리티와 내동해성을 높입니다.","고로슬래그·실리카·플라이애시 시멘트이고 AE시멘트는 아니다":"혼합시멘트는 고로슬래그, 실리카, 플라이애시 시멘트이고 AE시멘트는 해당하지 않습니다.","고로시멘트는 초기강도는 작고 장기강도는 비슷하며, 알루미나시멘트는 조기강도가 크다":"고로시멘트는 초기강도는 낮아도 장기강도가 비슷해지고, 알루미나시멘트는 조기강도가 큽니다.","고온 시멘트를 쓰지 않고 노반 마찰을 줄이고 단위수량을 많이 쓰지 않아 방지한다":"콘크리트 포장의 초기균열은 뜨거운 시멘트를 피하고 노반 마찰을 줄이며 물을 많이 쓰지 않아 막습니다.","고온 시멘트와 장시간 뙤약볕에 둔 골재를 쓰지 않고 저온의 물을 쓴다":"서중콘크리트에는 뜨거운 시멘트와 오래 햇볕에 놓인 골재를 피하고 찬물을 씁니다.","고정하중과 활하중을 합친 연직하중은 슬래브 두께와 관계없이 5.0kN/m2 이상을 본다":"슬래브 두께와 상관없이 고정하중과 활하중을 더한 연직하중은 최소 5.0kN/m2로 잡습니다.","곡선의 꼭지점은 절토에서 성토로, 저점은 성토에서 절토로 옮겨지는 점이다":"곡선 꼭지점에서는 절토가 성토로, 저점에서는 성토가 절토로 바뀝니다.","골재는 시트로 덮어 동결을 막고 조강시멘트를 써도 좋으며 염화물은 경화를 촉진한다":"골재는 시트로 덮어 얼지 않게 하고 조강시멘트를 써도 되며, 염화물은 경화를 촉진합니다.","골재를 용적으로 계량할 때 필요하며 공극 비율은 공극률이고 실적률은 그 보수이다":"부피로 계량할 때 필요한 값이고, 빈틈의 비율이 공극률이며 실적률은 공극률과 합해 전체가 되는 비율입니다.","골재 속 미립분이 늘면 단위수량·건조수축이 증가하고 블리딩은 감소하며 레이턴스는 늘어난다":"골재 속 미립분이 많아지면 단위수량과 건조수축이 늘고 블리딩은 줄며 레이턴스는 늘어납니다.","골재의 밀도·모양·입도·다짐방법에 따라 크게 달라진다":"골재 단위용적질량은 밀도, 모양, 입도, 다짐방법에 따라 크게 달라집니다.","공기량이 늘면 압축강도가 감소하고 가압 성형하면 강도가 커진다":"공기량이 많아지면 압축강도는 낮아지고, 눌러 성형하면 강도는 높아집니다.","공장 제조라 깨끗하고 입도가 적당하다":"인공 경량골재는 공장에서 만들어 깨끗하고 입도가 적당합니다.","과압밀 점토는 (＋)다일러턴시에 (－)간극수압":"과압밀 점토는 전단 중 부피가 늘어 (＋)다일러턴시와 (－)간극수압이 생깁니다.","과염소산암모늄이 주성분이고 다이너마이트보다 발화점이 높고 충격에 둔감하며 폭발력이 우수하다":"칼릿은 주성분이 과염소산암모늄이어서 다이너마이트보다 발화점이 높고 충격에 둔하며 폭발력이 좋습니다.","교각 위 브래킷을 설치해 이동하며 타설한다":"MSS는 교각 위에 브래킷을 설치해 거푸집을 옮겨 가며 경간마다 타설하는 공법입니다.","교대는 연직하중과 수평하중에 동시에 저항한다":"교대는 위에서 누르는 연직하중과 옆으로 미는 수평하중에 함께 견뎌야 합니다.","교대 배면 토사 및 재하중에 의한 토압":"교대의 수평력은 교대 배면 토사와 재하중이 만드는 토압입니다.","교대·옹벽 뒤채움 재료는 투수성이 양호해야 한다":"교대와 옹벽 뒤채움 재료는 물이 잘 빠지는 투수성이 좋아야 합니다.","교통에 의한 마모와 박리에 저항한다":"표층은 교통에 의한 마모와 박리에 견뎌야 합니다.","구조가 복잡하고 강성이 부족하다":"부벽식 댐은 구조가 복잡하고 강성이 부족합니다.","구조물 길이 방향에 일정 간격으로 만든 단면감소부분이다":"균열유발줄눈은 구조물 길이 방향으로 일정 간격마다 만든 단면감소 부분입니다.","구조 특성에 따라 중력식·캔틸레버식(T형)·부벽식으로 나눈다":"옹벽은 구조적 특성에 따라 중력식, 캔틸레버식(T형), 부벽식 세 종류로 구분합니다.","국부전단계수는 포함되지 않는다":"국부전단계수는 메이어호프 공식에 포함되지 않습니다.","군지수는 통일분류법의 인자가 아니고 CL은 소성이 큰 점토가 아니다":"군지수는 AASHTO 분류에서 쓰는 값이어서 통일분류법 인자가 아니며, CL은 소성이 작은 점토입니다.","굳은 암반이 아니어도 시공 가능하며 투수처리로 풍화암·퇴적층도 쓴다":"필댐은 기초가 굳은 암반이 아니어도 시공 가능하고, 투수처리를 하면 풍화암이나 퇴적층도 씁니다.","굴착저면이 부풀어 오르는 히빙":"히빙은 굴착저면이 흙의 압력으로 부풀어 오르는 현상입니다.","굵은골재는 5mm체 잔류분, 잔골재는 5mm체 통과분을 쓴다":"안정성시험은 굵은골재는 5mm체에 남은 것, 잔골재는 5mm체를 통과한 것을 씁니다.","굵은골재 최대치수 25mm, 프리텐션 프리스트레싱 시 강도 30MPa 이상이 표준이다":"프리텐션 도입 시 강도 30MPa 이상, 그라우트용 굵은골재 최대치수 25mm가 표준 기준입니다.","균열 수가 많아지고 폭도 커진다":"온도균열지수가 작으면 균열 수가 많아지고 균열 폭도 커집니다.","균열유발부는 철근 부식·누수 대책을 세우며 온도균열지수는 1.2~1.5로 제한한다":"균열유발부는 철근이 녹슬거나 물이 새지 않게 대책을 세우고 온도균열지수를 1.2~1.5로 제한합니다.","균열을 확실히 유도하려면 25% 이상으로 하고 간격은 20m가 아니다":"균열을 확실히 유도하려면 단면을 25% 이상 줄여야 하며 간격은 20m로 정하지 않습니다.","균열이 없도록 설계해 내구성·수밀성이 좋고 전단면을 유효하게 써 처짐이 작다. 강성이 커서 변형이 작은 것은 아니다":"PSC는 균열을 막아 내구성과 수밀성이 좋고 전단면을 써서 처짐이 작으나, 강성이 크다는 말은 맞지 않습니다.","균열 저항성·내구성·내충격성이 개선되고 유동성이 좋아지지는 않는다":"섬유보강으로 균열 저항성, 내구성, 내충격성이 좋아지지만 유동성이 좋아지지는 않습니다.","근입깊이·기초폭이 클수록 지지력이 크고 지하수 포화 시 감소하며 허용지지력은 qult의 1/3이다":"기초를 깊고 넓게 하면 지지력이 커지고 지하수로 포화되면 줄며, 허용지지력은 qult를 3으로 나눈 값입니다.","금속 알루미늄 분말과 시멘트 알칼리가 반응해 생기는 수소가스를 이용한다":"발포제는 금속 알루미늄 분말이 시멘트 알칼리와 반응해 내는 수소가스로 부풀립니다.","기상작용에 대한 골재의 내구성을 조사하는 시험이다":"안정성시험은 기상작용을 받아도 골재가 버티는 내구성을 조사하는 시험입니다.","기초가 다소 불량하면 침목·콘크리트 침목 기초공을 한다":"기초가 조금 나쁘면 침목이나 콘크리트 침목으로 기초공을 합니다.","기초가 양호하면 암거를 직접 매설해도 된다":"암거는 기초가 좋으면 땅을 파서 바로 묻어도 됩니다.","기초바닥이 매우 불량하면 말뚝기초를 하며, 부등침하 우려 기초에 잡석·조약돌을 포설하는 것은 아니다":"기초바닥이 몹시 나쁘면 말뚝기초를 하며, 부등침하가 걱정되는 곳에 잡석·조약돌을 까는 것은 아닙니다.","기초 전반에 그라우팅해 기초암반의 지내력·강도를 개량한다":"콘솔리데이션 그라우팅은 기초 전반에 주입해 기초암반의 지내력과 강도를 높입니다.","기초 중앙에서 최대가 아니다":"강성기초의 접지압은 기초 중앙이 아니라 모서리에서 가장 크게 나옵니다.","기층보다 골재 치수가 작고 노상 바로 위의 인공층은 표층이 아니다":"표층은 기층보다 골재 치수가 작으며, 노상 바로 위에 있는 인공층은 표층이 아닙니다.","기포가 동결 팽창응력을 흡수해 동결융해 저항성이 커진다":"기포가 물이 얼어 부푸는 응력을 흡수해 동결융해 저항성이 커집니다.","기폭약 또는 첨장약을 관체에 장전한 것이다":"뇌관은 기폭약이나 첨장약을 관 속에 채워 넣은 것입니다.","긴 구멍 굴착이 쉽고 버력 비산거리가 짧으며 폭약이 절약된다":"번컷은 긴 구멍을 뚫기 쉽고 버력이 멀리 날지 않으며 폭약이 절약됩니다.","깊은 토층의 시료는 기계 보링으로 채취한다":"깊은 토층에서 시료를 얻으려면 기계 보링을 씁니다.","깊이에 관계없이 좁은 장소·구조물 기초 준설에 적당하고 단단한 지반에는 부적당하다":"그래브선은 깊이와 관계없이 좁은 곳이나 구조물 기초 준설에 알맞고 단단한 지반에는 맞지 않습니다.","깊이에 따라 일정하나 장기간 쓰면 열화로 배수효과가 줄어든다":"페이퍼드레인의 배수단면은 깊이에 따라 같지만 오래 쓰면 열화로 배수 효과가 줄어듭니다.","끓임법(자비법)·증기법·열기법":"인공건조법에는 끓여서 말리는 자비법, 증기법, 열기법이 있습니다.","내구성 검사는 공기량·염소이온량을 측정하고 워커빌리티는 굵은골재 최대치수·슬럼프를 확인한다":"내구성은 공기량과 염소이온량을 재서 검사하고, 워커빌리티는 굵은골재 최대치수와 슬럼프로 가립니다.","내구성·수밀성이 크고 해수에 대한 화학 저항성이 크다":"포졸란 콘크리트는 내구성과 수밀성이 크고 해수에 대한 화학 저항성도 큽니다.","내식성이 우수하고 비흡수성이며 절연성·착색·투광성이 좋다":"플라스틱은 녹슬거나 물을 빨지 않고 절연성, 착색성, 투광성이 좋습니다.","넓은 범위 등분포하중이 작용":"압밀 문제의 전제는 넓은 범위에 하중이 고르게 작용하는 것입니다.","넓은 평판구조 두께 0.8m 이상일 때 적용하는 것이 표준이다":"매스콘크리트는 넓은 평판구조에서 두께 0.8m 이상일 때 적용하는 것이 표준입니다.","네트워크 공정표는 작성 및 수정이 쉽지 않다":"네트워크 공정표는 작성과 수정이 쉽지 않다는 단점이 있습니다.","노무비가 크고 소규모·얕은 곳에는 비경제적이다":"공기케이슨은 노무비가 커서 소규모이거나 얕은 곳에는 경제성이 떨어집니다.","노즐에서 토출되는 토출배합으로 표시하며 장기강도는 28일 압축강도를 기준으로 한다":"숏크리트 배합은 노즐에서 나오는 토출배합으로 나타내며 장기강도는 28일 압축강도로 삼습니다.","노컷·번컷·피라미드컷 등이다":"심빼기 발파에는 노컷, 번컷, 피라미드컷 등이 있습니다.","논리적이나 강도정수 추정에 한계가 있다":"정역학적 방법은 논리적이지만 강도정수를 추정하는 데 한계가 있습니다.","뇌산수은·질화납·DDNP이다":"기폭약에는 뇌산수은, 질화납, DDNP가 있습니다.","늘면 인장강도·항복점·경도가 증가한다":"탄소가 늘면 강의 인장강도, 항복점, 경도가 증가합니다.","늘수록 워커빌리티가 증가하나 과다하면 재료분리가 생기고 건조수축이 적다":"고성능감수제를 늘릴수록 워커빌리티가 커지지만 지나치면 재료분리가 생기고 건조수축은 적습니다.","늦어 초기수화열이 낮고 수밀성·내염성이 높아진다":"포졸란 반응이 느려서 초기 수화열이 낮고 수밀성과 내염성이 높아집니다.","니트로글리세린은 다이너마이트의 원료이다":"니트로글리세린은 다이너마이트를 만드는 원료입니다.","다공질 골재를 쓰면 동결융해 저항성이 떨어진다":"구멍이 많은 다공질 골재는 물이 차서 얼면 부서져 동결융해 저항성이 떨어집니다.","다르시 법칙·유선망·침투해석으로 구한다":"침투수량은 다르시 법칙, 유선망, 침투해석으로 구할 수 있습니다.","다져진 상태 토량÷자연상태 토량":"C는 다져진 상태의 토량을 자연상태 토량으로 나눈 토량변화율입니다.","다짐에너지가 클수록 최적함수비는 감소한다":"다짐에너지를 키우면 더 적은 물로도 조밀해져서 최적함수비는 줄어듭니다.","다짐이 양호하고 물의 침입에 따른 강도 저하가 적은 안정된 재료여야 한다":"뒤채움 재료는 다짐이 잘 되고 물이 들어와도 강도가 덜 떨어지는 안정된 재료여야 합니다.","다짐·함수량·현장밀도시험이다":"노상 품질시험은 다짐, 함수량, 현장밀도시험으로 합니다.","단계 순서는 P→D→C→A에서 바뀌지 않는다":"사이클 단계는 P, D, C, A 순서가 정해져 있어 순서가 바뀌지 않습니다.","단계·활동·공정원칙과 연결원칙이며 경험원칙은 아니다":"PERT의 원칙은 단계, 활동, 공정원칙과 연결원칙이며 경험원칙은 없습니다.","단면이 하단으로 갈수록 증가하는 말뚝은 감소 방법이 아니며, 부마찰력의 원인은 지하수위 상승이 아니다":"아래로 갈수록 굵어지는 말뚝은 부마찰력 저감 방법이 아니고, 이 힘은 지하수위 상승 때문에 생기지 않습니다.","단위수량을 20~30% 줄여 고강도 콘크리트 제조에 쓴다":"고성능감수제는 단위수량을 20~30% 줄일 수 있어 고강도 콘크리트에 씁니다.","단위수량을 늘려 염분을 희석시키는 것":"단위수량을 늘려 염분을 묽게 하는 방법은 염해 대책이 아닙니다.","단위수량을 되도록 적게 쓴다":"단위수량을 되도록 적게 쓰면 콘크리트가 치밀해져 내구성이 좋아집니다.","단위수량을 줄이고 블리딩을 감소시키며 연행공기가 볼베어링처럼 워커빌리티를 개선한다":"AE제는 연행공기가 볼베어링처럼 구르며 워커빌리티를 높여 단위수량과 블리딩을 줄입니다.","단위수량이 적은 된비빔, AE제·감수제, 입도 양호 골재, 높은 분말도로 줄이며 철근 부착은 감소한다":"블리딩은 된비빔, AE제·감수제, 입도 좋은 골재, 곱게 간 시멘트로 줄이며 철근 부착력은 오히려 떨어집니다.","단위수량이 적을수록, 초기 습윤양생을 충분히 할수록 수축이 작다":"물을 적게 쓰고 초기에 습윤양생을 충분히 하면 건조수축이 작게 일어납니다.","단위시멘트량은 물-시멘트비 결정 기준이 아니다":"단위시멘트량은 물-시멘트비를 정하는 기준이 아니라 정해진 뒤 따라오는 값입니다.","단위시멘트량은 물-시멘트비에서 결정하고 슬럼프는 작업이 가능한 범위에서 작게 한다":"물-시멘트비로 단위시멘트량을 정하고, 슬럼프는 시공할 수 있는 한도에서 작게 둡니다.","단위시멘트량이 많고 응력이 크고 재하 재령이 작을수록 크리프가 크다":"재령이 짧을 때 하중을 받거나 응력이 크거나 단위시멘트량이 많으면 크리프가 커집니다.","단위시멘트량이 많은 부배합이 빈배합보다 좋고 플라이애시·AE제도 개선 효과가 있다":"시멘트를 많이 넣은 부배합이 빈배합보다 반죽이 좋고, 플라이애시나 AE제도 워커빌리티를 높입니다.","댐 축방향 상류 쪽에 해 차수를 목적으로 하며 더 깊다":"커튼 그라우팅은 댐 축방향 상류 쪽에 깊이 해서 물이 새지 않게 막는 차수가 목적입니다.","도로·활주로·댐 포장용 혼합물의 결합재로 쓴다":"스트레이트 아스팔트는 도로, 활주로, 댐 포장용 혼합물의 결합재로 씁니다.","도입 직후 최대 압축응력의 1.7배 이상이다":"프리스트레싱 직후 최대 압축응력의 1.7배 이상 강도가 있어야 도입 응력을 견딥니다.","도화선 심약은 흑색화약이며 흑색화약 주성분은 초석, 다이너마이트 주성분은 니트로글리세린이다":"도화선 심약은 흑색화약이고, 흑색화약은 초석, 다이너마이트는 니트로글리세린이 주성분입니다.","동결공법·대기압공법·웰포인트공법":"공사 중에만 쓰는 일시적 공법에는 동결공법, 대기압공법, 지하수 배수 공법이 있습니다.","동결·세굴에 안전한 최소 근입깊이를 가지고 시공 가능하며 경제적이어야 한다":"기초 깊이는 동결과 세굴에 안전한 최소 근입깊이 이상이어야 하며 시공이 가능하고 경제적이어야 합니다.","동역학 공식은 Engineering-News·Sander 등이다":"Engineering-News와 Sander 공식은 박을 때의 타격 에너지로 지지력을 추정하는 동역학 공식입니다.","동일 시험자가 2회 측정한 결과가 ±0.03 이내여야 한다":"시멘트 비중시험은 같은 사람이 두 번 잰 값의 차이가 ±0.03 이내여야 합니다.","두들길 때 엷게 펴지는 성질":"전성은 두드릴 때 얇게 펴지는 성질입니다.","록·샌드·레이크 아스팔트와 아스팔타이트이다":"천연 아스팔트에는 록, 샌드, 레이크 아스팔트와 아스팔타이트가 있습니다.","마모율 40% 이하, 0.08mm체 통과량 1.0% 이하, 절대건조밀도 2.50g/cm3 이상이다":"부순 굵은골재는 닳음 40% 이하여야 하고 0.08mm체 통과 1.0% 이하, 절대건조밀도 2.50g/cm3 이상을 갖춰야 합니다.","마샬 안정도는 소성변형에 대한 저항값이고 흐름값은 소성변형의 값이다":"마샬 안정도는 소성변형에 버티는 힘이고 흐름값은 소성변형이 생긴 양입니다.","마찰계수·탄성·충격저항·내노화성이 크다":"고무혼입 아스팔트는 마찰계수, 탄성, 충격저항, 내노화성이 큽니다.","많을수록 최적함수비는 증가하고 곡선 기울기는 완만하다":"세립토나 점토분이 많으면 최적함수비가 커지고 다짐곡선의 기울기는 완만해집니다.","많이 넣을수록 팽창률과 압축강도가 계속 증가하는 것은 아니다":"팽창재는 많이 넣는다고 팽창률과 압축강도가 계속 늘지는 않습니다.","말뚝 1본 지지력에 본수를 곱한 값이 아니다":"군항 지지력은 말뚝 1본의 지지력에 본수를 곱한 값과 같지 않습니다.","말뚝 두께 증가·전기 방식·도장으로 부식에 대비한다":"강말뚝은 두께를 늘리고 전기 방식을 쓰고 도장해서 부식에 대비합니다.","말뚝 선단에 구근을 만들어 지지력을 키울 수 있다":"말뚝 끝을 넓힌 구근을 만들면 선단 지지력을 키울 수 있습니다.","말뚝을 좁은 간격으로 박으면 단항인가 군항인가를 검토한다":"말뚝을 촘촘히 박으면 한 개씩 작용하는지 무리로 작용하는지 따져야 합니다.","말뚝 표면을 아스팔트로 코팅해 줄이며 지지력을 증가시키지 않고 직접기초 지지력 감소 요인도 아니다":"말뚝 표면에 아스팔트를 입히면 마찰이 줄지만 지지력을 늘리지는 않고, 직접기초 지지력을 줄이는 요인도 아닙니다.","매우 짧은 기간에 고강도가 얻어진다":"고압증기양생을 하면 아주 짧은 기간에 고강도를 얻습니다.","메쌓기보다 높이 쌓을 수 있다":"찰쌓기는 모르타르로 붙여 쌓아 메쌓기보다 높이 쌓을 수 있습니다.","면화약(TNT 등)을 심약으로 한 것이며 대폭파·수중폭파에서 뇌관 대신 쓴다":"도폭선은 TNT 같은 화약을 심약으로 하여 대폭파나 수중폭파에서 뇌관 대신 씁니다.","모관 상승고·흙의 투수계수·동결온도 지속시간":"동상은 모관 상승고, 흙의 투수계수, 동결온도 지속시간의 영향을 받습니다.","모관상승 부분은 (－)간극수압이 생겨 유효응력이 증가하며 스토크스 법칙은 영향이 없다":"모관상승 구간에는 음의 간극수압이 걸려 유효응력이 커지며, 스토크스 법칙은 이와 무관합니다.","모래·사질토에는 진동롤러, 고함수비 점질토에는 습지용 불도저가 적합하다":"모래와 사질토는 진동롤러가, 함수비 높은 점질토는 습지용 불도저가 알맞은 다짐 기계입니다.","모어 응력원에서 전단응력이 최대인 점을 연결해 구한다":"응력경로는 모어 응력원에서 전단응력이 최대인 점들을 이어 구합니다.","모어 응력원은 임의 평면의 응력상태를 나타내며 응력상태는 파괴포락선 위쪽에 존재할 수 없다":"모어 응력원은 한 평면의 응력상태를 보이며, 파괴포락선의 위쪽에는 응력상태가 존재할 수 없습니다.","무근콘크리트에서 거북등 균열이 난다":"무근콘크리트에서는 알칼리골재반응으로 거북등 모양 균열이 납니다.","무주수법 용기는 7L 이상, 주수법 용기는 5L 이상이고 골재 수정계수를 겉보기 공기량에서 뺀다":"무주수법 용기는 7L 이상, 주수법 용기는 5L 이상이고 겉보기 공기량에서 골재 수정계수를 뺍니다.","물-시멘트비 50% 이하, 단위시멘트량 370kg 이상이 표준이다":"수중콘크리트는 물-시멘트비를 50% 이하, 단위시멘트량을 370kg 이상으로 잡는 것이 표준입니다.","물-시멘트비가 같으면 굵은골재 최대치수가 클수록 강도는 작아진다":"물-시멘트비가 같을 때는 굵은골재 최대치수가 클수록 압축강도가 작아집니다.","물-시멘트비가 같을 때 최대치수가 커지면 압축강도는 감소하며 너무 크면 재료분리가 생긴다":"같은 물-시멘트비에서는 최대치수를 키울수록 압축강도가 낮아지고, 지나치면 재료분리도 생깁니다.","물-시멘트비가 클수록 압축강도가 저하되고 습윤양생이 공기 중 양생보다 강도가 크다":"물-시멘트비가 크면 강도가 떨어지고, 물을 머금게 하는 습윤양생이 공기 중 양생보다 강도를 더 높입니다.","물-시멘트비를 작게 하고 포졸란을 적당량 혼합한다":"재료분리는 물-시멘트비를 작게 하고 포졸란을 알맞게 섞어 줄입니다.","물-시멘트비·슬럼프·잔골재율이 들고 잔골재 최대치수는 아니다":"시방배합표에는 물-시멘트비, 슬럼프, 잔골재율이 들어가며 잔골재 최대치수는 들지 않습니다.","물과 골재를 가열하며 시멘트는 직접 가열하지 않는다":"한중콘크리트는 물과 골재를 데워 쓰고 시멘트는 직접 가열하지 않습니다.","믹싱 후 경과시간에 따른 슬럼프 손실이 있고, 분산제에 포졸리스·다렉스(AE 계열)는 해당하지 않는다":"고성능감수제는 믹싱 후 시간이 지나면 슬럼프가 줄고, 포졸리스·다렉스(AE 계열)는 분산제로 해당하지 않습니다.","밀도는 2회 평균과의 차 0.01g/cm3 이하, 흡수율은 0.05% 이하로 한다":"밀도 시험은 두 번 잰 평균과의 차가 0.01g/cm3 이하, 흡수율은 0.05% 이하이어야 합니다.","밀도·전단강도가 증가하고 부착력이 증대된다":"다짐으로 밀도와 전단강도가 늘고 부착력도 커집니다.","바론 정사각형 배치에서 사주 간격 d의 유효원 지름은 de＝1.13d이다":"바론 방식으로 정사각형 배치할 때 드레인 사이 간격 d에 대응하는 유효원 지름은 1.13d입니다.","바퀴자국·측방유동으로 나타나는 안정성 부족 파손":"소성변형은 바퀴자국이나 측방유동으로 나타나는 안정성 부족 파손입니다.","반발경도법은 표면 타격의 반발 정도로 강도를 추정하고 복합법은 반발경도법과 초음파속도법을 병용한다":"반발경도법은 표면을 쳐서 튀는 정도로 강도를 추정하고 복합법은 반발경도법과 초음파속도법을 함께 씁니다.","반복·경험 있는 사업에 쓴다":"CPM은 같은 일을 반복했거나 경험이 있는 사업에 알맞습니다.","반응성 골재·알칼리·수분이 필요":"반응하려면 반응성 골재, 알칼리, 수분이 세 가지 모두 있어야 합니다.","발열량이 적어도 장기강도가 작은 것은 아니며 한중콘크리트에는 적합하지 않다":"포졸란은 열이 적게 나도 장기강도는 작지 않지만 한중콘크리트에는 맞지 않습니다.","밤낮에 관계없이 작업이 가능하다":"쉴드 공법은 낮이든 밤이든 가리지 않고 작업할 수 있습니다.","방사형·하프형·팬형·별형이다":"사장교 케이블 형상은 방사형, 하프형, 팬형, 별형으로 나눕니다.","방수성·내충격성·내마모성이 좋고 인장·휨·부착강도가 커진다":"폴리머시멘트 콘크리트는 방수성, 내충격성, 내마모성이 좋고 인장·휨·부착강도가 커집니다.","방습구조 장소에 품종별로 구분해 저장한다":"시멘트는 습기를 막는 구조의 장소에 품종별로 나누어 저장합니다.","배수층 역할로 노상토 지지력을 증대시키는 것은 아니다":"프라임코트는 배수층이 되어 노상토 지지력을 높이는 것이 아닙니다.","배합 수량이 많을수록, 석고를 첨가할수록, 풍화될수록 늦어진다":"배합 수량이 많거나 석고를 더 넣거나 풍화될수록 응결·경화가 늦어집니다.","배합이 바뀔 때마다 하고 1일 1회 또는 120m3마다 1회 실시한다":"압축강도 시험은 배합이 바뀔 때마다 하고 하루에 한 번이나 120m3마다 한 번 합니다.","벌목은 가을~겨울이 적당하고 목재는 가볍고 가공이 쉬우나 재질이 균일하지 않다":"벌목은 가을에서 겨울이 알맞고, 목재는 가볍고 가공이 쉬우나 재질이 고르지 않습니다.","벤토나이트 안정액을 쓰며 소음·진동이 적다":"지하연속벽은 벤토나이트 안정액으로 구멍 벽을 지탱하므로 소음과 진동이 적습니다.","벤트 공법·이렉션 트러스·새들 공법":"비계를 이용하는 공법에는 벤트 공법, 이렉션 트러스, 새들 공법이 있습니다.","벽체가 흙 쪽으로 밀려 작용하는 토압이며 토압분포가 삼각형에 가까운 것은 옹벽이다":"수동토압은 벽체가 흙 쪽으로 밀릴 때 작용하며 토압분포가 삼각형에 가까운 것은 옹벽입니다.","벽체 강성과 지수성이 높고 주변 지반 침하를 막으며 큰 지지력을 얻는다":"지하연속벽은 벽체 강성과 지수성이 높아 주변 침하를 막고 큰 지지력을 줍니다.","변형률이 중립축 거리에 비례하고 재료를 탄성체로 본다":"PSC 해석은 변형률이 중립축에서 멀어질수록 비례해 커진다고 보고 재료를 탄성체로 가정합니다.","보조기층과 아스팔트 혼합물의 융합을 좋게 한다":"프라임코트는 보조기층과 아스팔트 혼합물이 잘 붙게 하는 역할을 합니다.","보조기층의 모세관 상승을 차단하고 기층·보조기층을 파손과 강우 침투로부터 보호한다":"프라임코트는 보조기층의 모세관 상승을 끊고 기층과 보조기층을 파손과 빗물 침투로부터 지킵니다.","보통 재령 28일 압축강도로 검사한다":"물-시멘트비 검사는 보통 재령 28일 압축강도로 합니다.","보통 포틀랜드시멘트를 쓰면 5일 정도 직접 해수에 닿지 않게 보호한다":"보통 포틀랜드시멘트 콘크리트는 5일쯤 해수에 직접 닿지 않게 보호한 뒤에 노출합니다.","본바닥 변화 적응이 곤란하고 지반에 따라 적용이 제약되며 라이닝이 두꺼워야 하는 것은 아니다":"TBM은 본바닥이 바뀌면 적응하기 어렵고 지반에 따라 쓸 수 없는 경우가 있으며, 라이닝을 두껍게 할 필요는 없습니다.","부분굴착·트렌치컷을 쓰며, 근입을 짧게 하거나 표토 하중을 키우는 것은 대책이 아니다":"히빙에는 부분굴착이나 트렌치컷이 대책이고, 근입을 줄이거나 표토 하중을 키우는 쪽은 효과가 없습니다.","부분포화로 뒷채움 흙무게 증가":"뒷채움 흙이 부분적으로 물을 머금으면 흙의 무게가 늘어납니다.","부재 길이가 길수록, 단면적이 작을수록 늘음량이 커진다":"부재 길이가 길고 단면적이 작을수록 같은 힘에서 늘음량이 커집니다.","부재 최소치수 1/5, 철근 최소 순간격 3/4을 넘지 않는다":"굵은골재 최대치수는 부재 최소치수의 5분의 1, 철근 최소 순간격의 4분의 3을 넘지 않게 합니다.","부재 최소치수의 1/4을 넘지 않으며 일반 콘크리트는 20mm 또는 25mm가 표준이다":"무근콘크리트는 부재 최소치수의 4분의 1 이하로 하며 일반 콘크리트는 20mm 또는 25mm가 표준입니다.","부재 최소치수의 1/5을 넘지 않는다":"철근콘크리트 굵은골재 최대치수는 부재 최소치수의 5분의 1 이하로 제한합니다.","부재 치수가 작을수록 크며 장기간에 걸쳐 진행한다":"부재 치수가 작을수록 크리프가 크고 변형이 장기간에 걸쳐 진행됩니다.","부재치수 기준은 넓은 평판구조의 0.8m 이상과 다르다":"하단이 구속된 벽체는 부재치수 기준이 넓은 평판구조의 0.8m 이상과 다릅니다.","분말도가 높으면 풍화되기 쉽다":"시멘트가 가늘수록 표면적이 커서 습기를 쉽게 받아 풍화되기 쉽습니다.","분말도를 높이고 무기혼화재를 섞고 둥근 입형 골재를 쓰면 좋아진다":"시멘트를 곱게 하고, 무기혼화재를 섞고, 둥근 골재를 쓰면 워커빌리티가 좋아집니다.","분사 부착면을 매끄럽게 하는 것은 리바운드를 늘린다":"부착면을 매끄럽게 하면 뿜은 재료가 잘 붙지 않아 리바운드가 늘어납니다.","불도저·덤프트럭·벨트컨베이어이고 탬퍼는 다짐기계이다":"불도저, 덤프트럭, 벨트컨베이어는 운반용 기계이고 탬퍼는 흙을 다지는 기계입니다.","블록보링·스네이크보링·머드캐핑으로 큰 덩어리를 조각낸다":"큰 덩어리는 블록보링, 스네이크보링, 머드캐핑으로 다시 쪼개 작게 만듭니다.","블록쌓기 콘크리트 틀 옹벽과 돌쌓기 옹벽":"블록쌓기 콘크리트 틀 옹벽과 돌쌓기 옹벽은 구조형식 분류에 들지 않습니다.","블론보다 점도·연화점이 낮고 감온성이 크며 신장성이 우수하다":"스트레이트 아스팔트는 블론보다 점도·연화점이 낮고 온도 변화에 민감하며 신장성이 좋습니다.","블리딩이 많으면 레이턴스도 많아져 이음부에 불리하다":"블리딩이 많으면 레이턴스도 늘어 이음부에서 부착이 약해집니다.","비결정질 유리질 재료로 잠재수경성을 가진다":"고로슬래그 미분말은 결정이 없는 유리질 재료로 잠재수경성을 가집니다.","비교적 고속으로 운행할 수 있다":"타이어 도저는 바퀴가 달려 비교적 고속으로 운행할 수 있습니다.","비비기 전에 미리 믹서에 모르타르를 부착시키고 연속믹서의 최초 배출 콘크리트는 쓰지 않는다":"비비기 전 믹서에 모르타르를 먼저 묻혀 두며, 연속믹서에서 처음 나온 콘크리트는 쓰지 않습니다.","비중은 약 1.0~1.1, 인화점은 250~320℃이다":"아스팔트 비중은 약 1.0~1.1이고 인화점은 250~320℃ 범위입니다.","비중은 온도가 오를수록 낮아지고 컨시스턴시는 온도에 크게 좌우된다":"아스팔트 비중은 온도가 오르면 낮아지고 컨시스턴시도 온도에 크게 좌우됩니다.","비중이 1.1~1.25로 스트레이트 아스팔트보다 약간 크고 내유성이 좋다":"포장용 타르는 비중이 1.1~1.25로 스트레이트 아스팔트보다 조금 무겁고 기름에 잘 견딥니다.","비중이 작은 골재를 쓰는 것은 내구성 향상법이 아니다":"비중이 작은 골재를 고르는 것은 콘크리트 내구성을 올리는 방법에 들지 않습니다.","비중이 큰 목재가 강도가 크고 심재가 변재보다 강도가 크다":"목재는 비중이 클수록 단단하고, 같은 나무에서 속의 심재가 변재보다 강합니다.","비카트 침은 응결시간 시험, 강열감량은 풍화 정도, 수경률은 원료 조합비와 연결된다":"응결시간은 비카트 침, 풍화 정도는 강열감량, 원료 조합비는 수경률로 짝지어 봅니다.","비탈면 안정에 필요한 전단강도와 큰 지지력을 가져야 한다":"성토재는 비탈면을 안정시킬 전단강도와 충분한 지지력을 갖춘 흙이어야 합니다.","비표면적으로 시멘트 입자의 굵고 가는 정도를 나타낸다":"분말도는 비표면적으로 시멘트 입자가 얼마나 굵고 가는지를 나타냅니다.","빈입도이면 균등계수가 작고 간극비가 크며 다지기 힘들다":"입경가적곡선이 급하면 빈입도여서 균등계수가 작고 간극비가 크며 다지기 힘듭니다.","빈입도 흙의 투수계수는 작지 않다":"빈입도 흙은 간극이 커서 투수계수가 작지 않습니다.","빠를수록 압축강도는 높게 평가된다":"재하속도가 빠를수록 압축강도가 높게 평가됩니다.","사석부 위에 직립부를 얹어 경사제와 직립제의 장점을 합친 형식이다":"혼성제는 아래 사석부와 위 직립부를 합쳐 경사제와 직립제의 장점을 함께 살린 방파제입니다.","사용량이 1% 이하라 배합계산에서 고려하지 않는다":"혼화제는 사용량이 1% 이하로 적어 배합계산에서 부피를 따로 고려하지 않습니다.","사질토 지지력은 재하판 폭에 비례하고 점토 지지력은 재하판 폭과 무관하다":"사질토는 재하판이 넓을수록 지지력이 커지지만 점토는 재하판 폭이 지지력에 영향을 주지 않습니다.","사질 해저의 대량준설과 매립을 동시에 한다":"펌프선은 모래가 많은 해저에서 대량 준설과 매립을 동시에 합니다.","살수·침수·자연방치로 제거하고 철근 방청, 방청제를 쓴다":"해사의 염분은 물을 뿌리거나 담그거나 자연방치로 빼고, 철근 방청과 방청제를 씁니다.","상부구조 고정하중·활하중에 의한 지점 최대하중·충격하중":"교대의 연직력은 상부구조 고정하중, 활하중에 의한 지점 최대하중과 충격하중입니다.","상부구조와 하부구조로 나눈다":"교량은 상부구조와 하부구조로 나누어 봅니다.","상부하중을 안전하게 지지하고 지지력에 안정해야 한다":"기초는 위의 하중을 안전하게 받아내고 지지력에 대해 안정적이어야 합니다.","샌드드레인·페이퍼드레인·프리로딩이 맞고 바이브로플로테이션은 아니다":"점토지반 탈수에는 샌드드레인, 페이퍼드레인, 프리로딩을 쓰고 바이브로플로테이션은 모래 다짐 공법이라 해당하지 않습니다.","서중콘크리트나 운반거리가 먼 레미콘에서 슬럼프 손실·콜드조인트를 막는다":"지연제는 서중콘크리트나 먼 곳에서 오는 레미콘에서 슬럼프 손실과 콜드조인트를 막습니다.","서중콘크리트나 장거리 수송 레미콘의 워커빌리티 저하를 막는다":"서중콘크리트나 장거리 수송 레미콘에서 워커빌리티가 떨어지는 것을 막습니다.","석재는 예각부와 요철을 피하고 1m3 정도 크기로 쓰며 압축강도 50MPa 이상을 경석이라 한다":"석재는 모서리와 요철을 피해 1m3 안팎으로 쓰고, 압축강도 50MPa 이상인 돌을 경석이라 부릅니다.","석탄·갈탄 골재는 황산을 만들고 연한 석편은 강도를 낮추며 점토는 부배합에도 불리하다":"석탄이나 갈탄이 섞인 골재에서는 황산이 생기고, 무른 돌 조각은 강도를 낮추며, 점토는 부배합에서도 해롭습니다.","석탄·석유가 주원료이며 경량·강인하고 대량생산이 가능하다":"플라스틱은 석탄과 석유가 주원료이며 가볍고 질기고 대량생산이 가능합니다.","석회(CaO)·실리카(SiO2)·알루미나(Al2O3)":"시멘트의 주성분은 석회(CaO), 실리카(SiO2), 알루미나(Al2O3)입니다.","석회암은 석회물질이 침전·응고한 것, 혈암은 점토가 불완전하게 응고된 것이다":"석회암은 석회물질이 가라앉아 굳은 암석이고, 혈암은 점토가 덜 굳어 생긴 암석입니다.","선행압밀하중·압축지수·팽창지수를 구하며 압밀계수는 구하지 못한다":"e-logP 곡선에서는 선행압밀하중, 압축지수, 팽창지수를 구하며 압밀계수는 구하지 못합니다.","설계기준 20MPa는 27MPa, 40MPa는 49MPa 배합강도이다":"시험 기록이 없으면 설계기준강도 20MPa는 27MPa, 40MPa는 49MPa를 배합강도로 씁니다.","설계기준강도보다 크게 정하며 두 식 중 큰 값을 쓴다":"배합강도는 설계기준강도보다 크게 잡고 두 식으로 구한 값 중 큰 쪽을 씁니다.","설계기준강도의 2/3 이상이고 14MPa 이상일 때 해체한다":"슬래브와 보 밑면은 설계기준강도의 3분의 2 이상, 14MPa 이상일 때 해체합니다.","설계기준압축강도는 30MPa 이상이고 AE감수제·고성능감수제로 기상작용에 저항한다":"해양콘크리트는 설계기준압축강도 30MPa 이상으로 하고 AE감수제나 고성능감수제로 기상작용에 저항합니다.","설계기준압축강도는 일반적으로 40MPa 이상이다":"고강도콘크리트는 설계기준압축강도가 보통 40MPa 이상인 콘크리트를 가리킵니다.","설비가 간단하고 공사비가 싸다":"오픈케이슨은 설비가 간단하고 공사비가 쌉니다.","설비투자가 비싸 초기 투자비가 크다":"TBM은 설비투자가 커서 초기 투자비 부담이 큽니다.","섬유방향에 평행할 때 가장 강하고 압축강도보다 크다":"목재 인장강도는 섬유방향에 평행할 때 가장 크고 압축강도보다 큽니다.","섬유포화점 이하에서는 함수율이 클수록 강도가 작아진다":"섬유포화점 아래에서는 수분이 많아질수록 목재가 약해집니다.","세공경을 작게 해 수밀성을 높이고 블리딩이 작으며 유동성이 향상된다":"고로슬래그 미분말은 세공경을 줄여 수밀성을 높이고 블리딩이 작으며 유동성을 좋게 합니다.","셋 모두 굴착기계이며 스크레이퍼는 굴착·운반 기계이다":"백호, 드래그라인, 클램셸 같은 셋은 굴착기계이고 스크레이퍼는 굴착과 운반을 겸합니다.","소요 워커빌리티 범위에서 단위수량이 최소가 되도록 시험으로 정한다":"잔골재율은 필요한 워커빌리티 범위에서 단위수량이 가장 적도록 시험으로 정합니다.","소음이 없어 도회지에 적합하고 선단지지력을 확실히 하며 말뚝 본수를 줄인다":"피어기초는 공사 소음이 없어 도심에 알맞고, 선단지지력을 확실히 해 말뚝 수를 줄일 수 있습니다.","쇄암선은 해저 암반을 파쇄하고 디퍼선은 파쇄·발파된 암석 준설에 부적당하지 않다":"쇄암선은 해저 암반을 부수고, 디퍼선은 부서지거나 발파된 암석 준설에도 쓸 만합니다.","수동과 주동 사이에 있고 주동보다 크다":"정지토압계수는 수동과 주동 사이에 있으며 주동보다 큽니다.","수밀성 기준 물-시멘트비는 50% 이하, 슬럼프 50·65mm의 허용차는 ±15mm이다":"물이 새지 않게 하려면 물-시멘트비를 50% 이하로 잡고, 슬럼프 50·65mm 목표는 ±15mm 오차까지 허용합니다.","수밀성·동결융해 저항 증가, 재료분리·블리딩 감소가 목적이며 철근 부착력 증진은 아니다":"AE제는 수밀성과 동결융해 저항을 늘리고 재료분리와 블리딩을 줄이려고 쓰며 철근 부착력 증진은 목적이 아닙니다.","수밀성이 좋아 수리구조물에 적합하다":"플라이애시 콘크리트는 수밀성이 좋아 수리구조물에 맞습니다.","수분 증가·굴착에 따른 구속력 감소·지진 수평력 증가로 일어난다":"사면은 물이 늘고, 굴착으로 붙잡는 힘이 줄고, 지진으로 수평력이 더해질 때 무너집니다.","수산화칼슘이 공기 중 탄산가스와 반응":"중성화는 수산화칼슘이 공기 중 탄산가스와 만나 반응하면서 시작됩니다.","수직응력에 비례하지 않으며 흐트러진 흙은 전단강도가 낮고 압축성이 크다":"점착력과 내부마찰각은 수직응력에 비례하지 않으며, 흐트러진 흙은 전단강도가 낮고 압축성이 큽니다.","수축보상용은 (150~250)×10⁻⁶, 화학적 프리스트레스용은 (200~700)×10⁻⁶이다":"화학적 프리스트레스용이 수축보상용보다 팽창을 크게 주며 각각 (200~700)×10⁻⁶, (150~250)×10⁻⁶입니다.","수평저항력은 증가하지 않고 감소한다":"물이 스며들면 옹벽의 수평저항력은 늘지 않고 오히려 줄어듭니다.","수평투영면적당 최소 2.5kN/m2 이상이다":"활하중은 수평투영면적당 최소 2.5kN/m2 이상으로 잡습니다.","수화반응을 늦춰 응결·경화시간을 길게 한다":"응결지연제는 수화반응을 늦춰 응결과 경화 시간을 길게 합니다.","수화반응을 늦춰 응결시간을 길게 한다":"지연제는 수화반응을 늦춰 응결시간을 길게 합니다.","수화발열이 느려 조기강도가 낮고 혼합률 70%에서는 중성화 속도가 빨라진다":"고로슬래그 미분말은 수화발열이 느려 조기강도가 낮고, 혼합률 70%에서는 중성화가 빨라집니다.","수화속도가 매우 빠르고 발열량이 크며 수축도 크다":"수화가 아주 빨라 열이 많이 나고 수축도 크다는 점이 이 클링커 광물의 특징입니다.","수화열과 건조수축이 적고 해수에 대한 내화학성이 크며 단위수량은 줄어든다":"플라이애시 콘크리트는 수화열과 건조수축이 적고 해수에 대한 내화학성이 크며 단위수량이 줄어듭니다.","수화열이 보통보다 적고 건조수축이 가장 적으며 조기강도는 작다":"중용열시멘트는 수화열이 적고 건조수축이 가장 작은 대신 조기강도가 작습니다.","수화열이 적어 매스콘크리트에 좋고 해수·공장폐수·하수에 접하는 콘크리트에 적당하다":"고로시멘트는 수화열이 적어 매스콘크리트에 좋고 해수, 공장폐수, 하수에 닿는 콘크리트에 알맞습니다.","수화열이 적은 시멘트를 쓰고 단위시멘트량을 줄이며 골재 치수를 크게 한다":"매스콘크리트는 수화열이 적은 시멘트를 쓰고 단위시멘트량을 줄이며 골재 치수를 키워 균열을 줄입니다.","수화·응결이 빠르고 초기강도가 크며 워커빌리티가 좋다":"분말도가 높으면 수화와 응결이 빨라 초기강도가 크고 워커빌리티가 좋습니다.","쉬스관의 크기는 감소 원인이 아니다":"쉬스관의 크기는 프리스트레스가 감소하는 원인에 들지 않습니다.","슈트 배출구에서 타설면까지 1.5m 이하이고, 콘크리트를 친 직후 거푸집 외측에 충격을 줄 수 있다":"슈트 배출구에서 타설면까지는 1.5m 이하로 하며, 친 직후 거푸집 바깥에 충격을 줄 수도 있습니다.","스트레이트보다 유동성·방수성이 작고 탄력성이 크다":"블론 아스팔트는 스트레이트보다 유동성과 방수성이 작고 탄력성이 큽니다.","스트레이트보다 응집성·부착성이 크다":"고무혼입 아스팔트는 스트레이트 아스팔트보다 응집성과 부착성이 큽니다.","스트레이트 아스팔트와 같이 취급하지 않고, 비중은 침입도가 작을수록 크다":"아스팔타이트는 천연 아스팔트라 스트레이트 아스팔트와 같이 다루지 않으며 침입도가 작을수록 비중이 큽니다.","슬럼프·Vee-Bee·구관입·흐름시험이다":"워커빌리티는 슬럼프, Vee-Bee, 구관입, 흐름시험으로 재며, 비카 장치는 응결시간용입니다.","슬럼프는 크게 하지 않고 1회 타설 높이를 줄인다":"슬럼프는 크게 하지 않고 한 번에 치는 높이를 줄여야 열이 덜 쌓입니다.","습기 침투를 막는 곳에 보관하고 포대는 15포대 이상 쌓지 않는다":"팽창재는 습기가 스미지 않는 곳에 보관하고 포대는 15포대 이상 쌓지 않습니다.","습윤양생을 길게 하면 중성화가 늦어지고 장기강도가 커지며 거푸집이 건조하면 살수한다":"습윤양생을 오래 하면 중성화가 늦어지고 장기강도가 커지며 거푸집이 마르면 물을 뿌립니다.","시공기계의 트래피커빌리티가 확보되고 다루기 쉬우며 압축침하가 작아야 한다":"시공기계 주행이 가능한 트래피커빌리티가 있고, 다루기 쉬우며 압축침하가 적은 재료가 알맞습니다.","시공 부위의 모멘트를 줄이려 추진코(steel nose)를 쓴다":"ILM은 시공 부위 모멘트를 줄이려고 추진코(steel nose)를 앞에 붙여 밀어냅니다.","시공할 때 면을 거칠게 하고 이물질을 제거한다":"기존 콘크리트 면에 숏크리트를 하려면 면을 거칠게 하고 이물질을 제거합니다.","시료가 받는 응력의 변화과정을 응력공간에 궤적으로 나타낸 것이다":"응력경로는 시료가 받는 응력이 변해 간 과정을 응력공간에 선으로 그린 것입니다.","시멘트가 대기 중 수분을 흡수해 수화작용하는 것이다":"시멘트 풍화는 시멘트가 공기 중 수분을 흡수해 수화작용을 하는 것입니다.","시멘트 강도는 모르타르 강도로 측정하며 풀의 강도가 아니다":"시멘트 강도는 풀이 아니라 모르타르로 만들어 측정합니다.","시멘트량을 늘리고 13mm 이하 골재를 쓴다":"시멘트량을 늘리고 13mm 이하 골재를 쓰면 리바운드가 줄어듭니다.","시멘트 분말도·골재 최대치수·부재 크기의 영향을 받고 배합방법은 주요 인자가 아니다":"배합방법은 건조수축의 주요 인자가 아니며, 분말도와 골재 최대치수, 부재 크기가 영향을 줍니다.","시멘트 비표면적이 작거나 콘크리트 온도가 높으면 감소하고 단위잔골재량이 많으면 증가한다":"연행공기량은 시멘트 비표면적이 작거나 온도가 높을 때 줄고, 단위잔골재량이 많을 때 늘어납니다.","시멘트 알칼리와 골재의 실리카가 반응":"알칼리골재반응은 시멘트의 알칼리와 골재 속 실리카가 반응하는 현상입니다.","시멘트와 물의 수화반응은 발열반응이며 주요 생성물에 탄산칼슘은 없다":"수화반응은 열을 내는 발열반응이며, 생성되는 주요 물질 가운데 탄산칼슘은 들어 있지 않습니다.","시멘트 입자를 분산시켜 단위수량을 줄이며 촉진제의 주성분은 나프탈렌설폰산염이 아니다":"감수제는 시멘트 입자를 흩어 주어 단위수량을 줄이며, 촉진제의 주성분이 나프탈렌설폰산염인 것은 아닙니다.","시방서 또는 책임기술자가 지시하는 배합이며 단위량으로 표시한다":"시방배합은 시방서나 책임기술자가 지시하는 배합으로 단위량으로 나타냅니다.","시프스풋·그리드·탬퍼풋 롤러이고 탠덤롤러는 아니다":"탬핑롤러에는 시프스풋, 그리드, 탬퍼풋 롤러가 있고 탠덤롤러는 여기에 들지 않습니다.","시험체 3개 압축강도의 평균값이다":"한 번의 시험값은 공시체 세 개의 압축강도를 평균해 얻습니다.","시험횟수 15회의 표준편차에는 보정계수 1.16을 곱한다":"표준편차를 구한 시험횟수가 15회뿐이면 보정계수 1.16을 곱해 키웁니다.","신뢰도 및 표준편차와 설계서비스지수 손실량도 입력자료이다":"신뢰도, 표준편차, 설계서비스지수 손실량도 AASHTO 설계 입력자료입니다.","신속히 운반하고 즉시 쳐서 충분히 다지며 사전에 충분한 계획을 세운다":"콘크리트는 빨리 운반해 곧바로 쳐서 충분히 다지고 미리 계획을 세워야 합니다.","심성암으로 조직이 균질하고 내구성·강도가 크지만 내화성이 작다":"화강암은 땅속 깊이서 굳은 심성암으로 조직이 균질하고 내구성과 강도가 크나 내화성이 작습니다.","십자형 베인을 압입해 회전모멘트로 원통형 전단파괴를 일으킨다":"십자형 베인을 흙에 박고 돌려 회전모멘트로 원통 모양의 전단파괴를 일으킵니다.","아스팔트보다 투수성·흡수성이 크고 물이 있어도 골재 접착성이 뛰어나다":"포장용 타르는 아스팔트보다 투수성과 흡수성이 크고 물이 있어도 골재에 잘 붙습니다.","아스팔트 콘크리트 기층 다짐에는 머캐덤·탠덤·타이어 롤러를 쓴다":"아스팔트 콘크리트 기층은 머캐덤, 탠덤, 타이어 롤러로 다집니다.","아스팔트 포장보다 국부 파손 보수가 쉬운 것은 아니다":"콘크리트 포장은 국부적으로 파손된 곳을 아스팔트 포장보다 쉽게 고치지 못합니다.","안정도·흐름값·공극률과 관계가 있고 마모감량은 아니다":"마샬시험은 안정도, 흐름값, 공극률과 관련이 있고 마모감량은 다른 시험 항목입니다.","안정성이 높고 여굴 낭비가 적으며 노무비가 절약된다":"TBM은 안정성이 높고 여굴로 인한 낭비가 적으며 노무비를 아낄 수 있습니다.","알루미늄은 강력한 탈산제로 강조직을 미립화하고 망간은 강도·경도·인성을 증가시킨다":"알루미늄은 강한 탈산제로 강조직을 잘게 만들고, 망간은 강도, 경도, 인성을 높입니다.","알칼리-골재반응은 초기균열의 원인이 아니다":"알칼리-골재반응은 굳은 뒤 오랜 시간이 지나 나타나므로 초기균열의 원인이 아닙니다.","알칼리골재반응을 억제하고 내화학약품성을 높이며 혼합률이 늘면 일정 수준까지 압축강도가 증가한다":"실리카퓸 콘크리트는 알칼리골재반응을 억제하고 내화학약품성이 높으며, 혼합률을 늘리면 일정 수준까지 압축강도가 커집니다.","알칼리골재반응을 촉진할 수 있고 단위결합재량을 작게 하면 내구성이 떨어진다":"해수는 알칼리골재반응을 부추길 수 있고, 단위결합재량이 적으면 내구성이 부족해집니다.","알키드 수지는 열가소성이 아니다":"알키드 수지는 가열하면 굳는 쪽이라 열가소성이 아닙니다.","암석 특유의 천연적으로 갈라진 금은 절리이다":"절리는 암석에 자연적으로 갈라져 있는 금입니다.","압력을 일정하게 하고 벽면과 직각으로 분사한다":"리바운드를 줄이려면 압력을 일정히 하고 벽면과 직각으로 뿜습니다.","압력의 크기에 비례하지 않는다":"투수계수는 압력 크기에 따라 비례해서 변하지 않는다고 가정합니다.","압밀촉진 공법으로 시공이 빠르고 주변 교란이 적다":"페이퍼드레인은 압밀을 앞당기는 공법으로 시공이 빠르고 주변 지반을 덜 흐트러뜨립니다.","압밀침하량이 최종의 절반이면 평균압밀도는 50%이다":"압밀이 끝난 침하량의 절반만큼 가라앉은 시점의 평균압밀도는 50%에 해당합니다.","압밀 후 전단 시 배수를 허용한다":"CD 시험은 압밀을 끝낸 뒤 전단 중에도 물이 빠지도록 허용하는 시험입니다.","압송이 쉽고 재료분리·블리딩이 적어야 하며 경화 중 팽창해야 한다":"주입 모르타르는 압송이 쉽고 재료분리와 블리딩이 적어야 하며 굳는 동안 팽창해야 합니다.","압축강도 5MPa 이상이면 해체한다":"확대기초, 보 옆, 기둥 측면 거푸집은 압축강도가 5MPa 이상이면 해체합니다.","압축강도가 가장 크고 인장·휨·전단강도는 작다":"석재는 압축강도가 가장 크고 인장, 휨, 전단강도는 그보다 작습니다.","압축강도·내동해성·내구성(수밀성)으로 정한다":"물-시멘트비는 압축강도, 내동해성, 내구성(수밀성)을 기준으로 정합니다.","압축강도·예민비·변형계수를 구하며 비배수 조건 결과를 준다":"일축압축시험으로 압축강도, 예민비, 변형계수를 구하며 결과는 비배수 조건의 값입니다.","압축성이 높거나 좋은 재료는 안 된다":"압축성이 큰 재료는 침하를 일으키므로 뒤채움에 쓰지 않습니다.","압축성이 커지거나 부착성이 감소하는 것은 아니다":"다짐은 압축성을 키우거나 부착성을 줄이는 작업이 아닙니다.","앞면 수직벽·밑판·수직부벽으로 이루어지며 뒷부벽은 T형보, 앞부벽은 직사각형보로 설계한다":"부벽식 옹벽은 벽·밑판·부벽 세 부분이며, 뒤쪽 부벽은 T형보로, 앞쪽 부벽은 직사각형보로 설계합니다.","액성한계시험은 노상 시험종목이 아니고 프루프롤링은 노체 시험종목이 아니다":"노상에는 액성한계시험을, 노체에는 프루프롤링을 시험종목으로 넣지 않습니다.","약액주입·프리로딩·다짐 모래말뚝":"약액주입, 프리로딩, 다짐 모래말뚝은 효과가 영구적이라 일시적 공법이 아닙니다.","약하고 모양이 나빠 고강도용으로 부적당하며 응회암·경석·화산자갈이 있다":"천연 경량골재는 약하고 모양이 나빠 고강도용으로 맞지 않으며 응회암, 경석, 화산자갈이 있습니다.","얇은 판으로 높은 강도를 얻고 곡면가공을 해도 균열이 적다":"합판은 얇은 판을 겹쳐 높은 강도를 내고 곡면 가공을 해도 균열이 적습니다.","양생은 20±2℃ 습윤 상태이며 하중 속도는 압축응력도 증가율 매초 0.6±0.4MPa이다":"공시체는 20±2℃의 습윤 상태에서 양생하고, 압축응력도가 매초 0.6±0.4MPa 늘도록 하중을 줍니다.","어느 정도 취성이 있고 철근 부착강도가 감소하며 외관은 주로 흰색이다":"고압증기양생 콘크리트는 취성이 조금 있고 철근 부착강도가 줄며 색은 주로 희게 나옵니다.","어스드릴 공법은 케이싱 없이 회전식 버킷을 쓰고, 강재원통 흙막이는 연약점토에 쓴다":"케이싱을 쓰지 않고 회전 버킷으로 굴착하는 방법이 어스드릴이고, 연약점토에서는 강재원통으로 흙막이를 합니다.","에폭시·불포화 폴리에스테르를 많이 쓰며 고강도로 만들려면 골재 강도가 더 높아야 한다":"에폭시와 불포화 폴리에스테르가 주로 쓰이며, 더 강하게 하려면 골재 자체가 더 단단해야 합니다.","여굴을 줄이는 스무스블라스팅·프리스플리팅·라인드릴링·쿠션블라스팅이다":"조절발파에는 스무스블라스팅, 프리스플리팅, 라인드릴링, 쿠션블라스팅이 있어 여굴을 줄입니다.","여수로를 제체 위에 설치하지 못하고 지진 등에 취약하며 높은 댐 축조에는 불리하다":"필댐은 여수로를 제체 위에 둘 수 없고 지진에 약하며 높은 댐을 쌓기 어렵습니다.","연못공법·치환공법·깊은기초로 팽창성을 줄인다":"팽창성 점토는 연못공법, 치환공법, 깊은기초로 팽창성을 줄입니다.","연속 35점 중 한계 밖 1점 이내는 관리상태이며 100점 중 4점 이내는 관리상태 기준이 아니다":"연속한 35점 가운데 한계를 벗어난 점이 1개 이하면 관리상태이고, 100점 중 4점 이하라는 기준은 아닙니다.","연속 3회 시험값 평균이 설계기준강도 이상이면 합격이며 관리도·히스토그램을 이용한다":"합격 여부는 연속 3회 시험값의 평균이 설계기준강도를 넘는지로 가르며 관리도와 히스토그램을 활용합니다.","연속 타설 시 콜드조인트를 방지하며 숏크리트에는 쓰지 않고 조기탈형 목적도 아니다":"이어 칠 때 콜드조인트를 막아 주며 숏크리트에는 쓰지 않고 조기탈형이 목적도 아닙니다.","연약~중간 점성토에 적용하며 내부마찰각은 측정할 수 없다":"베인전단시험은 연약에서 중간 정도의 점성토에 쓰며 내부마찰각은 측정하지 못합니다.","연직으로 일정 간격 찔러 넣고 횡방향으로 이동시키지 않는다":"내부진동기는 연직으로 일정 간격마다 꽂으며 옆으로 끌고 다니지 않습니다.","연한 스트레이트 아스팔트에 휘발성 용제를 가해 유동성을 높인 것이다":"컷백 아스팔트는 연한 스트레이트 아스팔트에 휘발성 용제를 섞어 묽게 만든 것입니다.","열이나 약품에 의해 재용융되는 것이고 탄성계수는 작다":"열가소성은 열이나 약품으로 다시 녹는 성질이며 탄성계수가 작습니다.","염화물이 많으면 물-시멘트비를 작게 한다":"염화물이 많은 환경에서는 물-시멘트비를 작게 해 염분이 스며드는 것을 줄입니다.","염화물이온 침투를 억제해 철근 부식 억제 효과가 있다":"고로슬래그 미분말은 염화물이온이 스며드는 것을 줄여 철근 부식을 억제합니다.","염화비닐·폴리에틸렌·아크릴 수지":"열가소성 수지에는 염화비닐, 폴리에틸렌, 아크릴 수지가 있습니다.","온도가 낮을수록·시멘트량이 적을수록 공기량이 늘고 플라이애시는 공기량을 늘리지 않는다":"공기량은 낮은 온도와 적은 시멘트량에서 늘어나고, 플라이애시를 쓴다고 늘지는 않습니다.","온도가 높고 분말도가 높고 C3A가 많을수록 응결·경화가 빠르다":"온도가 높고 분말도가 높고 C3A가 많으면 응결과 경화가 빨라집니다.","온도가 높으면 슬럼프가 감소하며 둥근 잔골재가 부순 모래보다 불리하지 않다":"온도가 높으면 슬럼프가 줄어들며, 둥근 잔골재가 부순 모래보다 불리한 것은 아닙니다.","완전 건조한 공시체가 포화된 것보다 강도가 크며 편심재하 시 강도는 작게 나온다":"공시체가 완전히 건조하면 포화된 것보다 강도가 크고, 하중이 한쪽으로 치우치면 강도가 작게 나옵니다.","외기온도 25℃ 이상이면 비비기부터 타설 완료까지 1.5시간, 25℃ 미만이면 허용 이어치기 간격은 2시간이다":"더운 25℃ 이상에서는 비비기에서 타설까지 1.5시간 이내, 25℃ 미만에서는 이어치기 간격 2시간 이내입니다.","용지매수가 쉽고 보상비가 적어야 하며 용수·붕괴 염려가 없고 배수가 좋아야 한다":"토취장은 용지매수가 쉽고 보상비가 적으며, 용수나 붕괴 염려가 없고 배수가 좋은 곳을 고릅니다.","운반 중 재료분리가 있었으면 충분히 다시 비벼 균질하게 한 뒤 친다":"운반 중 재료분리가 있었다면 다시 충분히 비벼 균질하게 한 뒤에 쳐야 합니다.","운반 중 충격·화기에 주의하고 장기 보존 시 흡습·동결·온·습도 변질을 막는다":"화약류는 운반 중 충격과 불을 조심하고, 오래 두면 습기, 동결, 온·습도 변화로 변질될 수 있어 막아야 합니다.","운송시간을 줄이고 운반 직전에 물을 추가하지 않아 막는다":"운송시간을 줄이고 운반 직전에 물을 더 넣지 않으면 슬럼프 저하를 막을 수 있습니다.","워커빌리티가 좋고 단위수량을 줄이며 초기강도 향상은 아니다":"플라이애시시멘트는 워커빌리티가 좋고 단위수량을 줄이지만 초기강도를 높이지는 않습니다.","워커빌리티가 좋고 재료분리가 작다":"포졸란 콘크리트는 반죽이 부드러워 워커빌리티가 좋고 재료분리가 작습니다.","워커빌리티를 높이고 단위수량을 줄이며 수화열이 작다":"플라이애시 콘크리트는 워커빌리티가 좋아 단위수량을 줄일 수 있고 수화열도 작습니다.","원리는 보일의 법칙이며 시료를 3층으로 나눠 각 층 25회 다진다":"압력법 공기량 시험은 보일의 법칙을 원리로 하며 시료를 3층으로 나눠 각 층 25회 다집니다.","원심력 철근콘크리트 말뚝보다 고가이고 균열이 잘 안 생긴다":"PC말뚝은 원심력 철근콘크리트 말뚝보다 값이 비싸고 균열이 잘 생기지 않습니다.","원액으로 쓰고 소정량을 한꺼번에 첨가하며 계량오차는 1회 3% 이내이다":"유동화제는 원액으로 소정량을 한꺼번에 넣고 계량오차는 1회 3% 이내여야 합니다.","원유를 증류한 잔유물이며 역청유제는 역청을 미립자로 수중에 분산시킨 것이다":"석유 아스팔트는 원유를 증류하고 남은 잔유물이고, 역청유제는 역청을 물속에 미립자로 퍼뜨린 것입니다.","원칙적으로 할 수 없고 슬럼프·공기량 시험은 50m3마다 1회이다":"재유동화는 원칙적으로 하지 않으며 슬럼프·공기량 시험은 50m3마다 한 번 합니다.","웰포인트 공법도 공사 중에만 지하수를 제어한다":"지하수를 뽑아 제어하는 이 공법은 공사 중에만 효과가 있어 일시적 공법입니다.","웰포인트·샌드드레인·프리로딩이다":"탈수를 주로 하는 공법에는 지하수를 뽑는 공법과 샌드드레인, 프리로딩이 있습니다.","유기계 섬유는 아라미드·비닐론·폴리프로필렌이고 유리섬유는 무기계이다":"아라미드, 비닐론, 폴리프로필렌은 유기계 섬유이고 유리섬유는 무기계입니다.","유기질토 분류방법이 있고 기준은 0.075mm체 통과율 50%이다":"유기질토에는 별도 분류방법이 있고 구분의 기준은 0.075mm체를 통과하는 비율 50%입니다.","유해가스 발생이 많고 흡수성이 커서 터널공사에는 적합하지 않다":"칼릿은 유해가스가 많이 나오고 습기를 잘 빨아들여 터널공사에는 적합하지 않습니다.","유효연직응력에 Ko를 곱한 값이다":"유효수평응력은 유효연직응력에 정지토압계수 Ko를 곱해 구합니다.","유효응력이 전응력보다 클 수도 있고 정지토압계수 K0는 1보다 클 수 있다":"정지토압계수 K0는 1보다 클 수 있고, 유효응력이 전응력보다 큰 경우도 생깁니다.","응결은 시멘트 풀이 유동성과 점성을 잃고 굳는 현상이고 풍화는 공기 중 수분·CO2와의 반응이다":"풀이 굳어 흐름을 잃는 것이 응결이고, 공기 중 수분과 CO2를 만나 변하는 것이 풍화입니다.","응결이 빨라지고 소요수량이 증가하며 운반 중 슬럼프가 떨어진다":"서중콘크리트는 응결이 빨라지고 소요수량이 늘며 운반 중 슬럼프가 떨어집니다.","응력원이 파괴포락선과 접하지 않으면 전단파괴가 아니고, 전단력이 0인 면의 연직응력은 주응력이다":"원이 파괴선에 닿아야 전단파괴가 일어나며, 전단력이 0인 면에 걸린 연직응력은 주응력입니다.","응력은 어디나 동일하지 않다":"기초 밑면의 응력은 위치마다 달라서 어디서나 같지 않습니다.","이론상 정사각형이고 침투속도·동수경사는 유선망 폭에 비례하지 않는다":"유선망 사각형은 이론상 정사각형이며 침투속도와 동수경사는 유선망 폭에 비례하는 값이 아닙니다.","인공 경량골재 같은 다공질 골재 콘크리트에는 적용되지 않는다":"인공 경량골재 같은 다공질 골재 콘크리트에는 압력법 공기량 시험을 적용하지 않습니다.","인공 경량골재는 흡수량이 많아 건조 상태로 쓰면 안 되며 중량골재는 방사선 차폐 고밀도 콘크리트용이다":"인공 경량골재는 물을 많이 먹어 마른 채 쓰면 안 되고, 중량골재는 방사선 차폐용 고밀도 콘크리트에 씁니다.","인공포졸란이며 초기강도가 큰 것은 아니고, 미연탄소가 AE제를 흡착해 연행공기가 줄어든다":"플라이애시는 인공포졸란이며 초기강도가 큰 것은 아니고, 남은 탄소가 AE제를 빨아들여 연행공기가 줄어듭니다.","인장강도가 크고 차수·분리·배수성이 크다":"지오텍스타일은 인장강도가 크고 차수, 분리, 배수 기능이 뛰어납니다.","인장강도·경도가 증가하고 밀도는 약간 감소하며 신장은 줄어든다":"냉간가공을 하면 인장강도와 경도가 늘고 밀도는 조금 줄며 신장은 줄어듭니다.","인장강도와 균열 저항성을 높인 콘크리트이다":"섬유보강콘크리트는 섬유를 섞어 인장강도와 균열 저항성을 높인 콘크리트입니다.","인장력으로 가늘고 길게 늘어나는 성질":"연성은 인장력을 받아 가늘고 길게 늘어나는 성질입니다.","인장측 콘크리트 응력을 무시하지 않으며 긴장재 부착 전에는 덕트 단면적을 공제한다":"균열이 생기기 전에는 인장 쪽 콘크리트도 응력을 부담하는 것으로 보고, 부착 전 긴장재는 덕트 면적을 뺍니다.","인장·휨응력을 받는 곳에는 쓰지 않으며 휨응력 부재로도 쓰지 않는다":"석재는 인장·휨응력을 받는 곳에 쓰지 않고, 휨응력을 받는 부재로도 쓰지 않습니다.","인화점은 연소점보다 낮으며 약 25~60℃ 차이가 난다":"인화점은 연소점보다 낮아서 두 온도는 약 25~60℃ 벌어집니다.","일반 굴착 깊이 35~40m":"공기케이슨은 일반적으로 굴착 깊이 35~40m까지 적용합니다.","일평균기온 15℃ 이상에서 습윤 보호하며 막양생은 사전 시험으로 검토한다":"보통포틀랜드시멘트는 일평균기온 15℃ 이상일 때 습윤 보호하고, 막양생은 사전 시험으로 따져 봅니다.","임의 방향 시공이 가능하나 리바운드 손실과 분진이 크고 노즐맨 기술에 품질이 좌우된다":"숏크리트는 어느 방향이든 칠 수 있으나 리바운드 손실과 분진이 크고 노즐맨 기술에 따라 품질이 갈립니다.","입도가 일정할 때 실적률로 입형을 판정하며 조립률로 입형을 판정할 수는 없다":"입도가 일정한 조건에서는 실적률로 입형을 가리며 조립률로는 입형을 가릴 수 없습니다.","입도가 좋고 입형이 둥글면 좋아진다":"입도가 좋고 알이 둥글면 골재 사이 마찰이 줄어 워커빌리티가 좋아집니다.","입도분포·액성한계·소성지수·소성도·No.200체 통과율을 쓰며 군지수는 쓰지 않는다":"통일분류는 입도분포, 액성한계, 소성지수, 소성도, No.200체 통과율을 쓰고 군지수는 쓰지 않습니다.","입도분포와 군지수를 주요 인자로 쓴다":"AASHTO 분류는 입도분포와 군지수를 주요 인자로 삼습니다.","입도분포와 애터버그 한계로 흙을 분류한다":"통일분류법은 입도분포와 애터버그 한계, 곧 연경도를 기준으로 흙을 나눕니다.","입자 모양이 판상인 것은 몬모릴로나이트·일라이트·카올리나이트이다":"판 모양 입자의 점토광물에는 몬모릴로나이트, 일라이트, 카올리나이트가 있습니다.","입자의 면모화를 막기 위해 분산제를 쓰고 D30은 전체 무게 30%가 그보다 작은 입경이다":"비중계법은 입자가 엉기지 않도록 분산제를 쓰며, D30은 전체 무게의 30%가 그보다 작은 입경입니다.","자연상태÷다져진 상태가 아니다":"C의 분모는 자연상태 토량이므로 자연상태를 다져진 상태로 나누는 식은 틀립니다.","자연전위법·분극저항법·전기저항법이다":"철근부식은 자연전위법, 분극저항법, 전기저항법으로 평가합니다.","자체 수경성이 없으나 수화로 생긴 수산화칼슘과 반응하며 천연(화산재·규조토)과 인공(플라이애시·소성점토)이 있다":"포졸란은 스스로 굳지 않지만 수화로 생긴 수산화칼슘과 반응하며 천연(화산재·규조토)과 인공(플라이애시·소성점토)이 있습니다.","작업 순서를 확실히 파악하고 컴퓨터 공정관리가 편리하며 인원 배치 계획이 합리적이다":"네트워크 공정표는 작업 순서를 확실히 알 수 있어 컴퓨터 공정관리가 편리하고 인원 배치 계획이 합리적입니다.","작은 구조물 기초에 적합하지 않다":"피어기초는 작은 구조물에는 비용이 맞지 않아 적합하지 않습니다.","작은 변형에도 파괴되는 성질":"취성은 거의 늘어나지 않고 작은 변형에도 부서지는 성질입니다.","잔골재는 5mm체를 전부 통과하는 것으로 보고 골재는 공기 중 건조상태 기준이 아니다":"시방배합은 잔골재가 5mm체를 모두 통과한다고 보며 골재는 공기 중 건조상태가 기준이 아닙니다.","잔골재 없이 굵은골재만 채우고 모르타르를 주입하며 내열성·시공성이 좋고 건조수축이 작다":"프리팩트 콘크리트는 굵은골재만 먼저 채우고 모르타르를 주입하며 내열성과 시공성이 좋고 건조수축이 작습니다.","잔골재 염화물(NaCl 환산량)의 최대값은 0.3%가 아니다":"잔골재 염화물을 NaCl로 환산한 최대 허용치는 0.3%가 아닌 다른 값입니다.","잔골재 조립률 적정 범위는 2.3~3.1이고 골재는 깨끗하며 크고 작은 알이 골고루 섞여야 한다":"잔골재 조립률은 2.3~3.1 범위가 알맞고, 깨끗하면서 굵고 가는 알이 고루 섞인 골재가 좋습니다.","잠재수경성이 있어 초기강도는 작고 장기강도는 보통시멘트와 비슷하거나 크다":"고로시멘트는 잠재수경성 때문에 처음에는 약해도 시간이 지나면 보통시멘트와 비슷하거나 더 강해집니다.","재료를 구하기 쉽고 강도가 커 지지말뚝에 적합하며 N값 30 이상 굳은 토층 관통은 쉽지 않다":"원심력 RC 중공말뚝은 재료를 구하기 쉽고 강도가 커 지지말뚝에 맞지만 N값 30 이상 굳은 토층은 뚫기 어렵습니다.","재료를 미리 냉각하고 수축이음부를 두며 기존 콘크리트로 구속시키지 않는다":"재료를 미리 식히고 수축이음부를 두며 기존 콘크리트로 구속하지 않아야 균열이 줄어듭니다.","재료 운반 제한이 적으며 지반 속에서 제작·양생되므로 품질관리가 쉽지 않다":"현장타설말뚝은 재료 운반 제한이 적지만 지반 속에서 만들고 굳혀 품질관리가 쉽지 않습니다.","저장 중 약간이라도 굳은 시멘트는 쓰지 않고, 13포 제한은 반출을 쉽게 하는 이유만은 아니다":"저장 중 조금이라도 굳은 시멘트는 사용하지 않고, 13포 제한이 반출 편의 때문만은 아닙니다.","전기·열 전도율이 크고 광택이 있으며 상온에서 결정형 고체로 가공성이 좋다":"금속은 전기와 열을 잘 전하고 광택이 있으며 상온에서 결정형 고체로 가공성이 좋습니다.","전단강도가 증가하고 과잉간극수압이 소산되며 2차 압밀량은 유기질토에서 크다":"압밀이 진행되면 전단강도가 늘고 과잉간극수압이 사라지며 2차 압밀량은 유기질토에서 큽니다.","전단 시 (＋)다일러턴시로 부피가 팽창하고 peak가 생긴다":"조밀한 모래는 전단하면 (＋)다일러턴시로 부피가 늘어나고 peak가 나타납니다.","전단 시 배수를 허용하지 않는다":"UU 시험은 전단 중에 배수를 허용하지 않는 시험입니다.","전단응력이 전단강도를 넘으면 그 면을 따라 파괴된다":"흙 속 어느 면에서든 전단응력이 전단강도보다 커지면 그 면이 파괴면이 됩니다.","전응력이 늘어난 만큼 간극수압이 커지면 유효응력은 변화가 없다":"전응력이 늘어난 양만큼 간극수압이 오르면 흙입자가 받는 유효응력은 그대로입니다.","전자파 속도는 V＝C/√εr이다":"전자파레이더법에서 전자파 속도는 광속 C를 √εr로 나눈 값입니다.","전체와 부분의 관련을 이해하기 쉽고 중점관리가 쉽다":"네트워크 공정표는 전체와 부분의 관련을 이해하기 쉽고 중점관리가 쉽습니다.","절건밀도 2.5g/cm3 이상, 마모율 40% 이하이고 황산나트륨 5회 손실질량 한도가 있다":"굵은골재는 절건밀도 2.5g/cm3 이상, 마모율 40% 이하여야 하고 황산나트륨 5회 손실질량도 한도 안이어야 합니다.","절대건조 상태의 질량을 절대건조 체적으로 나눈 값이다":"진밀도는 절대건조 상태의 질량을 절대건조 상태의 체적으로 나눈 값입니다.","절토 구간은 상승곡선, 성토 구간은 하향곡선이다":"유토곡선은 절토 구간에서 오르고 성토 구간에서 내려갑니다.","점도를 일시적으로 낮춘 것으로 상온시공이 가능하며 용제 양과 질에 따라 성질이 달라진다":"컷백 아스팔트는 점도를 잠깐 낮춰 상온에서 시공하며 용제 양과 질에 따라 성질이 달라집니다.","점토가 이산구조이면 면모구조보다 투수계수가 작은 것이 보통이며 불포화토는 투수계수가 낮게 측정된다":"이산구조 점토는 면모구조보다 물이 덜 통하고, 불포화토는 실제보다 낮은 투수계수가 측정됩니다.","점토광물에 따라 결합구조와 팽창성이 다르다":"점토광물은 종류별로 결합구조가 다르며 그 때문에 팽창성도 서로 다릅니다.","점토덩어리 최대 1.0%, 표면 마모 받는 경우 0.08mm체 통과량 최대 3.0%이다":"잔골재에서 점토덩어리는 최대 1.0%, 표면이 닳는 곳에 쓰면 0.08mm체 통과량은 최대 3.0%입니다.","점토·실트·모래·자갈 순으로 점점 작아진다":"모관상승고는 점토, 실트, 모래, 자갈 순으로 점점 작아집니다.","점토지반을 관통하면 부마찰력을 검토하고 간격이 좁으면 응력이 깊이 미치므로 영향을 본다":"점토지반을 뚫는 말뚝은 부마찰력을 따지고, 간격이 좁으면 응력이 깊이 전달되어 영향을 봅니다.","점토 침하량은 재하판 폭과 무관하지 않으며, 침하가 완전히 멈출 때까지 하지 않는다":"점토 침하량은 재하판 폭의 영향을 받으며, 시험은 침하가 완전히 멎을 때까지 계속하지는 않습니다.","접선이 종축과 만나는 점이 점착력 C이고 UU 조건의 응력원은 수평축과 평행한 접선을 가진다":"모어원 접선이 종축을 자르는 높이가 점착력 C이고, UU 조건의 접선은 수평선과 나란합니다.","정규압밀 점토는 (－)다일러턴시에 (＋)간극수압이 생긴다":"정규압밀 점토는 전단하면 부피가 줄고 간극수압은 양(＋)으로 생깁니다.","정밀 천공·장약량 조절·방진공으로 줄이고 동시발파는 안 된다":"발파 진동은 정밀 천공, 장약량 조절, 방진공으로 줄이고 여러 발을 동시에 터뜨려서는 안 됩니다.","정수 중에서 트레미나 펌프·밑열림 상자로 타설하며 숏크리트는 아니다":"수중콘크리트는 흐르지 않는 물속에서 트레미, 펌프, 밑열림 상자로 치며 숏크리트 방식은 쓰지 않습니다.","정역학적 지지력 공식에는 Dörr·Terzaghi·Meyerhof 공식이 있다":"Dörr, Terzaghi, Meyerhof가 제시한 식은 정역학적 지지력 공식에 속합니다.","젖은 상태로 쓰는 것이 좋다":"경량골재는 물을 빨아들이므로 미리 적셔 젖은 상태로 쓰는 것이 좋습니다.","제설작업과 운반거리가 긴 곳에 유리하다":"타이어 도저는 제설작업이나 운반거리가 긴 곳에서 유리합니다.","제재 후 심재는 변재보다 썩기 어렵다":"제재한 목재에서는 심재가 변재보다 썩기 어렵습니다.","조강시멘트는 보통시멘트보다 크리프가 작고, 습도가 높을수록 커지지는 않는다":"조강시멘트는 보통시멘트보다 크리프가 작고, 습도가 높다고 해서 크리프가 커지지는 않습니다.","조기에 포졸란 반응이 일어나며 단위수량과 건조수축이 줄어드는 것은 아니다":"실리카퓸은 일찍부터 포졸란 반응을 일으키며, 이때 단위수량과 건조수축이 줄어드는 것은 아닙니다.","조립률 계산용 표준체에는 40·10·5·2.5·1.2·0.6·0.3mm 체가 있다":"조립률을 구할 때는 40, 10, 5, 2.5, 1.2, 0.6, 0.3mm 체를 씁니다.","조립토일수록, 깨끗한 모래일수록 동상이 잘 일어나지 않는다":"조립토나 깨끗한 모래는 모관으로 물이 잘 올라오지 않아 동상이 드뭅니다.","조밀한 모래는 전단 중 팽창(＋dilatancy)하고 느슨한 모래는 수축한다":"조밀한 모래는 전단 중 부피가 늘고 느슨한 모래는 부피가 줄어듭니다.","조암광물 성질·비율·공극 정도에 따라 달라지고 보통 절대건조비중이 아니다":"석재의 비중은 광물의 종류와 비율, 구멍이 얼마나 있는지에 달려 있어 절대건조비중과 같지 않습니다.","조암광물 집합상태에 따라 생기는 눈의 모양을 석리라 한다":"석리는 조암광물이 모인 상태에 따라 생기는 암석의 눈 모양입니다.","주공정선상 총여유시간(TF)은 0이며 공정 단축은 이 경로에서 한다":"주공정선에서는 총여유시간(TF)이 0이라 공정을 줄이려면 이 경로에서 줄입니다.","주변 지반이 말뚝보다 상대적으로 크게 침하":"주변 지반이 말뚝보다 상대적으로 더 많이 가라앉을 때 부마찰력이 생깁니다.","주위에 단층이 없어야 하며 중력댐 검사링은 균열·수축·온도·누수를 검사한다":"댐 기초 주변에는 단층이 없어야 하며, 중력댐 검사링은 균열, 수축, 온도, 누수를 검사합니다.","주응력면과 이루는 각은 45°이고 Mohr원은 하나만 그려진다":"일축압축시험의 파괴면은 주응력면과 45°를 이루며 Mohr원은 하나만 그려집니다.","중성화가 철근 위치에 닿으면 철근이 부식되기 시작한다":"중성화 깊이가 철근 위치까지 닿으면 철근 부식이 시작됩니다.","중심 관리는 작업단계(event)이고 미군수국에서 개발되었다":"PERT는 작업단계(event)를 중심으로 관리하며 미군수국에서 개발되었습니다.","지간은 공시체 높이의 3배이고 길이는 단면 한 변의 3배보다 8cm 이상 길다":"휨강도 시험의 지간은 공시체 높이의 3배이며, 공시체 길이는 단면 한 변의 3배에 8cm 이상을 더합니다.","지름의 2배 높이를 가진 원기둥형으로 한다":"압축강도 공시체는 지름의 2배 높이를 가진 원기둥으로 만듭니다.","지연형 감수제를 쓸 수 있고 장기강도는 증진되지 않는다":"서중에는 지연형 감수제를 쓸 수 있으며 이로 인해 장기강도가 늘지는 않습니다.","지질과 지하수위에 관계없이 시공할 수 있는 것은 아니다":"쉴드 공법도 지질과 지하수위에 따라 제약이 있어 아무 조건에서나 시공할 수는 없습니다.","지층 깊이에 따라 말뚝 길이를 자유롭게 조절할 수 있다":"현장타설말뚝은 지층 깊이에 맞춰 길이를 자유롭게 조절할 수 있습니다.","지표 하중에 의한 연직응력 증가량은 깊이가 깊어질수록 감소한다":"지표 하중 때문에 늘어나는 연직응력은 깊이가 깊어질수록 줄어듭니다.","지하 깊은 곳에서 시공할 수 있고 소음·진동이 적다":"쉴드 공법은 지하 깊은 곳에서 시공할 수 있고 소음과 진동이 적습니다.","지하수를 저하시키지 않아 인접 침하 우려가 적다":"공기케이슨은 지하수위를 낮추지 않아 이웃 지반이 가라앉을 우려가 적습니다.","지하수위에 영향을 받지 않고 지반을 균일하게 다지며 깊은 곳 다짐도 가능하다":"바이브로플로테이션은 지하수위와 무관하게 지반을 고르게 다지고 깊은 곳도 다질 수 있습니다.","지하수위 저하나 압밀 중인 연약지반, 성토·매립 지반에서 발생한다":"지하수위가 낮아지거나 연약지반이 압밀되거나 성토·매립이 있으면 부마찰력이 생깁니다.","지하수위 저하·모관수 차단층·화학약품 처리이며 동결깊이보다 얕게 치환하지 않는다":"동상은 지하수위를 낮추고 모관수 차단층을 두고 화학약품 처리로 막으며, 동결깊이보다 얕게 치환해서는 안 됩니다.","지하 슬래브·벽체·기초말뚝기둥 연결작업은 어렵다":"역타공법은 지하 슬래브, 벽체, 기초말뚝 기둥을 잇는 작업이 어렵다는 단점이 있습니다.","지하주벽을 먼저 시공해 지하수 차단이 쉽고 도심지에 유리하다":"역타공법은 지하주벽을 먼저 만들어 지하수 차단이 쉽고 도심지 공사에 유리합니다.","직교하고 유선은 서로 교차하지 않는다":"유선과 등수두선은 직각으로 만나며 유선끼리는 서로 가로지르지 않습니다.","직선 또는 곡선으로 나타나며 전응력으로만 나타내는 것은 아니다":"응력경로는 직선이나 곡선으로 나타나며 전응력으로만 그리는 것은 아닙니다.","짧으면 강도가 작고 너무 길면 골재 파쇄로 강도가 저하된다":"혼합시간이 짧으면 덜 섞여 강도가 낮고, 너무 길면 골재가 부서져 강도가 오히려 떨어집니다.","착암기를 싣고 굴착작업을 하도록 만든 장비이다":"점보드릴은 착암기를 실어 굴착작업을 하도록 만든 장비입니다.","철근이나 PC강선 부식을 방지하기 위해 쓴다":"방청제는 철근이나 PC강선이 녹스는 것을 막으려고 씁니다.","철근이 배치된 일반 구조물에서 균열 방지가 필요하면 1.5 이상이고 인장강도를 온도응력으로 나눈다":"철근이 배치된 일반 구조물에서 균열 방지가 필요하면 온도균열지수를 1.5 이상으로 하며, 지수는 인장강도를 온도응력으로 나눈 값입니다.","철근 최소 순간격의 3/4을 넘지 않는다":"철근 사이로 골재가 통과해야 하므로 철근 최소 순간격의 4분의 3을 넘지 않게 합니다.","철근콘크리트와 거푸집 중량이고 철근 포함 콘크리트 단위중량은 보통 24kN/m3이다":"고정하중은 철근콘크리트와 거푸집 자체 무게이고, 철근을 포함한 콘크리트 단위중량은 보통 24kN/m3로 봅니다.","철근 피복두께를 충분히 두고 균열폭을 작게 만든다":"염해를 막으려면 철근 피복두께를 충분히 두고 균열폭을 작게 만듭니다.","체가름으로 입도를, 황산나트륨 용액 반복 시험으로 안정성을 판정한다":"골재 입도는 체가름으로, 안정성은 황산나트륨 용액에 반복 담그는 시험으로 판정합니다.","초기강도가 매우 크나 장기강도는 떨어지며 숏크리트·물막이 공법에 쓴다":"급결제는 초기강도가 매우 크지만 장기강도는 떨어져 숏크리트와 물막이 공법에 씁니다.","초기강도가 크고 수화열이 큰 시멘트가 되며 석고량과는 관계없다":"수경률이 크면 초기강도와 수화열이 큰 시멘트가 되며 석고량과는 관계가 없습니다.","초기 과잉간극수압은 하중 크기와 같다":"하중이 가해진 직후 초기 과잉간극수압은 가해진 하중의 크기와 같습니다.","초기 동결융해 저항성을 높이려면 물-시멘트비를 작게 해야 한다":"물-시멘트비를 작게 하면 조직이 치밀해져 초기 동결융해 저항성이 높아집니다.","초미립 분말로 블리딩·재료분리를 줄이고 수밀성을 높인다":"실리카퓸은 입자가 아주 고운 분말이라 블리딩과 재료분리를 줄이고 수밀성을 높입니다.","촉진양생을 해도 품질확인 시험은 필요하며 팽창률은 재령 7일 시험치 기준이다":"촉진양생을 하더라도 품질확인 시험은 빼지 않으며, 팽창률은 재령 7일에 측정한 값을 씁니다.","촉진 양생을 해야 하는 것은 아니며 AE감수제 사용을 원칙으로 하지도 않는다":"고강도콘크리트는 촉진양생을 꼭 해야 하는 것이 아니고 AE감수제 사용이 원칙도 아닙니다.","촉진제는 보통 염화칼슘을 시멘트 질량의 2% 이하로 쓰며 급결제는 장기강도 증진이 크지 않다":"급결제는 장기강도를 크게 높이지 못하고, 촉진제로는 보통 시멘트 질량의 2% 이하 염화칼슘을 씁니다.","최소 비용 기울기를 갖는 공정부터 하며 활동(activity)은 단위작업이다":"공기 단축은 최소 비용 기울기를 가진 공정부터 하고, 활동(activity)은 단위작업을 뜻합니다.","충분한 피복두께를 확보하고 콜드조인트를 만들지 않는다":"피복두께를 충분히 확보하고 콜드조인트를 만들지 않아야 내구성이 오래갑니다.","침입도가 큰 아스팔트, 골재 최대치수가 작을 때, 아스팔트량이 많을 때 쉽다":"침입도가 큰 아스팔트, 작은 골재 최대치수, 많은 아스팔트량은 소성변형이 쉬운 조건입니다.","침입도가 클수록·채움재가 적을수록 감소하고 공극률 작은 골재일수록 증가한다":"침입도가 크거나 채움재가 적으면 안정도가 낮아지고, 공극률이 작은 골재일수록 높아집니다.","침입도는 온도가 오를수록 커지고 반죽질기를 나타낸다":"온도가 오르면 아스팔트가 물러져 침입도가 커지며, 이 값이 반죽질기를 나타냅니다.","침하량이 15mm에 달하거나 하중이 항복점을 넘거나 예상 접지압을 넘을 때 끝낸다":"평판재하시험은 침하량이 15mm에 이르거나 하중이 항복점 또는 예상 접지압을 넘으면 중단합니다.","침하량이 허용치를 넘지 않아야 하며 침하가 전혀 없어야 하는 것은 아니다":"침하량이 허용치 안에 있으면 충분하고, 침하가 하나도 없을 것까지 요구하지는 않습니다.","침하 우려 시 재진동 다짐을 하고 수축이음은 균열 유도를 위해 단면 감소를 둔다":"매스콘크리트는 침하 우려가 있으면 재진동 다짐을 하고, 수축이음은 균열 유도를 위해 단면 감소를 둡니다.","침하하는 지반이 말뚝을 아래로 끌어내리는 힘이다":"부마찰력은 가라앉는 지반이 말뚝을 아래로 끌어내리는 힘입니다.","캔틸레버식은 비계 이용 공법이 아니다":"캔틸레버식은 비계 없이 내밀어 가설하므로 비계 이용 공법이 아닙니다.","캔틸레버식·케이블식·부선(폰툰)식 공법":"비계를 쓰지 않는 가설공법은 캔틸레버식, 케이블식, 부선(폰툰)식입니다.","커튼·콘택트는 강도 개량용이 아니다":"커튼과 콘택트 그라우팅은 강도를 개량하려는 목적이 아닙니다.","케이슨은 정확한 위치를 확보해야 한다":"케이슨은 침하 중에도 정확한 위치를 확보해야 합니다.","코어 회수율과 10cm 이상 코어 길이 비율로 구한다":"RQD는 코어 회수와 10cm 이상 코어 길이의 비율을 바탕으로 암반 상태를 숫자로 나타냅니다.","콘크리트가 팽창해 균열이 생긴다":"알칼리골재반응이 생기면 콘크리트가 부풀어 올라 균열이 생깁니다.","콘크리트는 2층 이상 거의 같은 층으로 나눠 채우고 몰드는 16시간 이상 3일 이내에 뗀다":"콘크리트를 2층 이상 비슷한 두께로 나누어 채우고, 몰드는 16시간 이상 3일 이내에 벗깁니다.","콘크리트 단괴식 방파제는 보통방파제이다":"단괴 콘크리트 블록을 쌓은 방파제는 보통방파제로 분류합니다.","콘크리트를 타설하기 전에 한다":"받아들이기 품질검사는 콘크리트를 타설하기 전에 합니다.","콘크리트 슬래브가 교통하중을 휨 저항으로 지지하며 내구성이 좋고 유지·보수비가 싸다":"콘크리트 포장은 슬래브의 휨 저항으로 교통하중을 받아 내구성이 좋고 유지·보수비가 적게 듭니다.","콘크리트치기가 끝나면 발생해 대략 2~4시간에 끝난다":"블리딩은 콘크리트를 다 친 직후부터 시작해 대략 2~4시간이면 끝납니다.","쿨롱은 강체역학의 흙쐐기 이론이고 랭킨은 소성이론이다":"쿨롱은 흙쐐기를 강체로 보는 강체역학 이론이고 랭킨은 소성이론에 바탕을 둡니다.","크리프와 건조수축도 감소 원인이다":"콘크리트가 오래 하중을 받으며 변하는 크리프와 건조수축도 프리스트레스를 줄입니다.","타설한 콘크리트를 거푸집 안에서 횡방향으로 이동시키지 않는다":"친 콘크리트를 거푸집 안에서 옆으로 끌어 옮기면 재료분리가 생기므로 하지 않습니다.","탄산칼슘이 되며 중성화가 진행된다":"반응 결과 탄산칼슘이 생기면서 알칼리성이 낮아져 중성화가 진행됩니다.","토립자의 비중은 영향 요인이 아니다":"토립자의 비중은 투수계수에 영향을 주는 요인이 아닙니다.","토립자의 크기와 공극의 형상·배열의 영향을 받는다":"투수계수는 토립자의 크기와 공극의 형상·배열에 영향을 받습니다.","토질에 따라 침하 속도가 다르므로 사전에 조사한다":"지반에 따라 가라앉는 속도가 달라져서 시공 전에 토질을 조사해 둡니다.","토질이 양호하고 토량이 충분하며 기계 사용이 쉬워야 한다":"토취장은 토질이 좋고 토량이 충분하며 기계를 쓰기 쉬워야 합니다.","토질 확인과 정확한 지지력 측정이 가능하다":"공기케이슨은 사람이 내려가 토질을 눈으로 보고 지지력을 정확히 잴 수 있습니다.","투수계수 추정에 쓰이는 값이 아니며 소성지수는 점성이 클수록 크다":"액성지수는 투수계수를 추정하는 값이 아니며, 소성지수는 점성이 클수록 큽니다.","투수성이 양호해야 하며 건조밀도가 낮거나 점토를 많이 포함하면 안 된다":"도로 성토재는 물이 잘 빠져야 하고 건조밀도가 낮거나 점토가 많으면 안 됩니다.","투수성·흡수성·압축성이 감소한다":"다짐하면 투수성, 흡수성, 압축성이 줄어듭니다.","트렌치컷·어스앵커·아일랜드 공법이 있고 뉴매틱케이슨은 아니다":"개착공법에는 트렌치컷, 어스앵커, 아일랜드 공법이 있고 뉴매틱케이슨은 개착공법이 아닙니다.","파괴될 때까지의 에너지 흡수능력":"인성은 파괴될 때까지 에너지를 흡수하는 능력을 뜻합니다.","팽창률은 0~10%, 28일 압축강도는 20MPa 이상이다":"팽창성 그라우트는 팽창률이 0~10%이고 28일 압축강도가 20MPa 이상이어야 합니다.","팽창·수축 결점이 없고 방향에 따른 강도 차이가 없으며 신축 변형량은 적다":"합판은 방향성이 없어 팽창·수축 결점이 없고, 강도 차이와 신축 변형이 작습니다.","팽창재는 수밀성이 작아지는 경향이 있고 촉진제는 한중콘크리트에, 안료를 넣으면 강도가 저하된다":"팽창재는 수밀성이 떨어지기 쉽고, 촉진제는 한중콘크리트에 쓰며, 안료를 섞으면 강도가 낮아집니다.","펠레니우스는 절편 양쪽 합력이 0이라 가정하고, 비숍 간편법은 연직 합력을 0이라 가정하며 시행착오법으로 푼다":"펠레니우스는 절편 양쪽 힘의 합이 0이라 놓고, 비숍 간편법은 연직 힘의 합을 0으로 놓은 뒤 반복 계산합니다.","편심이 생기지 않게 하며, 초기 3m까지 안정한 것은 아니다":"침하 중 편심이 생기지 않게 해야 하며 초기 3m까지만 안정하면 된다는 뜻은 아닙니다.","평균선과 곡선이 만난 두 점 사이는 절·성토가 균형이며 단면별 절·성토량은 곡선에서 구하지 않는다":"평균선과 곡선이 만나는 두 점 사이는 절토량과 성토량이 균형이고, 단면별 양은 곡선에서 구하지 않습니다.","평균 인장강도는 500MPa 이상, 16℃ 이상에서 90° 굽혀 부러지지 않아야 한다":"강섬유는 평균 인장강도가 500MPa 이상이고, 16℃ 이상에서 90° 구부려도 부러지지 않아야 합니다.","포스트홀형 오거는 연약한 흙, 스크루형 오거는 단단한 흙에 적합하다":"연약한 흙에는 포스트홀형 오거가, 단단한 흙에는 스크루형 오거가 맞습니다.","포졸란·고로슬래그 미분말·플라이애시로 억제하고 단위시멘트량을 키우지 않는다":"포졸란, 고로슬래그 미분말, 플라이애시로 억제하며 단위시멘트량을 늘리는 것은 대책이 아닙니다.","포화도도 투수계수를 좌우한다":"포화도가 달라지면 물이 지나는 단면이 달라지므로 투수계수가 달라집니다.","포화점토에서 급속 파괴가 예상될 때 쓴다":"UU 시험은 포화점토가 짧은 시간에 파괴될 것으로 예상될 때 씁니다.","폭발력이 약해 큰 석재 채취에 쓰며 수중폭파는 불가능하고 연기가 많이 난다":"흑색화약은 폭발력이 약해 큰 돌을 캐는 데 쓰고, 수중폭파는 못 하며 연기가 많이 납니다.","폴리에틸렌은 열경화성이 아니다":"폴리에틸렌은 가열하면 다시 물러지는 열가소성이어서 열경화성이 아닙니다.","표건비중 2.62, 흡수율 1.5%인 굵은골재의 절대건조비중은 2.58이다":"표건비중과 흡수율을 알면 절대건조비중을 거꾸로 계산하며, 2.62와 1.5%에서는 2.58이 나옵니다.","표면가공으로 흡음·의장 효과를 얻고 규격화되어 능률적이다":"합판은 표면 가공으로 흡음과 의장 효과를 얻고 규격화되어 있어 작업 능률이 오릅니다.","표면수가 내부로 침입하는 것을 막는다":"표층은 표면의 물이 안으로 들어가는 것을 막아 줍니다.","표면수 없이 알 속 공극이 물로 찬 상태":"표면건조포화상태는 표면수는 없고 알 속 공극만 물로 가득 찬 상태입니다.","표면에 물이 있고 내부도 물이 찬 상태":"습윤상태는 알 속이 물로 차 있고 표면에도 물이 묻어 있는 상태입니다.","표면적이 작은 말뚝을 쓰고 선행하중으로 지반침하를 줄이며 큰 케이싱을 박아 차단한다":"표면적이 작은 말뚝, 선행하중으로 지반침하 감소, 큰 케이싱으로 흙과의 접촉 차단이 부마찰력 감소 방법입니다.","표준체(45μm)나 블레인법의 비표면적(cm2/g)으로 나타내고 블리딩이 커지지 않는다":"분말도는 45μm 표준체 잔량이나 블레인법 비표면적(cm2/g)으로 나타내며 분말도가 높다고 블리딩이 커지지는 않습니다.","표층박리(scaling)는 동결융해 피해의 일종이고 물로 포화되었을 때 피해가 가장 크다":"물에 포화된 상태에서 얼고 녹기를 되풀이하면 표층박리(scaling)가 가장 심하게 일어납니다.","표토 제거·배면 배수로 하중을 줄이고 근입깊이를 깊게 하며 지반을 개량한다":"히빙은 표토를 제거하고 배면 배수로 하중을 줄이며 근입깊이를 깊게 하고 지반을 개량해 막습니다.","품질 변동은 관리도로 파악하며 점이 한계선 밖으로 나가지 않아야 관리상태이다":"품질 변동은 관리도로 보고 점이 한계선 밖으로 나가지 않으면 관리상태입니다.","풍화는 고온·다습·고운 분말일수록 빠르며 비중은 풍화되면 감소한다":"풍화는 고온다습하고 분말이 고울수록 빠르며, 풍화되면 비중이 줄어듭니다.","풍화된 시멘트는 응결이 늦어지고 초기강도가 저하되며 비표면적이 감소한다":"풍화된 시멘트는 응결이 늦고 초기강도가 떨어지며 비표면적이 줄어듭니다.","풍화 저항이 가장 큰 석재는 화강암이며 공극률은 전 공극과 겉보기체적의 비이다":"풍화에 가장 강한 석재는 화강암이고 공극률은 전체 공극과 겉보기체적의 비입니다.","프리스트레싱 시 콘크리트 압축강도는 30MPa 이상이다":"프리텐션 방식은 프리스트레싱을 줄 때 콘크리트 압축강도가 30MPa 이상이어야 합니다.","프리스트레싱 후 8시간 경과 뒤 되도록 빨리 하며 물-결합재비 45% 이하, 굵은골재 최대치수 25mm가 표준이다":"그라우트는 긴장 작업 8시간이 지난 뒤 서둘러 넣으며 물-결합재비 45% 이하, 골재 최대 25mm를 표준으로 삼습니다.","플라스틱·레진 콘크리트이며 액상수지를 결합재로 쓰고 시멘트를 쓰지 않는다":"레진 콘크리트는 시멘트 대신 액상수지를 결합재로 쓰는 플라스틱 콘크리트입니다.","플라이애시·고로슬래그 등이고 사용량이 많아 배합계산에 부피를 고려한다":"혼화재는 플라이애시나 고로슬래그처럼 많이 쓰는 재료라 배합계산에 부피를 반영합니다.","피에조미터 재하 직후 물 상승고는 하중에 해당하는 높이이다":"피에조미터는 하중 직후 간극수압을 수두로 보여 주므로 물이 오른 높이가 하중에 해당하는 높이입니다.","하루 평균기온 4℃ 이하일 때 AE제·AE감수제를 쓴다":"하루 평균기온이 4℃ 이하이면 한중콘크리트로 보고 AE제나 AE감수제를 씁니다.","하류 쪽에 하는 것이 아니다":"콘솔리데이션 그라우팅을 하류 쪽에만 하는 것은 아닙니다.","하부구조이므로 상부구조가 아니다":"교대는 상부구조를 받치는 하부구조에 속합니다.","하중을 적게 받는 부분을 먼저 떼고 거푸집은 자중과 시공하중에 견딜 때 해체한다":"하중을 덜 받는 부분부터 떼고, 거푸집은 자중과 시공하중을 견딜 만할 때 해체합니다.","한 구획 안은 완료될 때까지 연속 타설하고 표면은 거의 수평이 되게 친다":"한 구획은 끝날 때까지 이어서 치고 표면이 거의 수평이 되게 칩니다.","한 대 위에 여러 대의 착암기를 장치할 수 있다":"점보드릴은 한 대 위에 착암기 여러 대를 장치할 수 있습니다.","한 변 길이는 굵은골재 최대치수의 4배 이상이며 10cm 이상이다":"휨강도 시험 공시체는 한 변 길이를 굵은골재 최대치수의 4배 이상, 10cm 이상으로 합니다.","한중은 보온·급열양생, 매스는 프리쿨링·파이프쿨링, 서중은 저온 혼합수·지연형 감수제를 쓴다":"날씨와 구조에 따라 한중은 보온·급열, 매스는 프리쿨링·파이프쿨링, 서중은 찬 혼합수·지연형 감수제로 대응합니다.","할선탄성계수로 응력-변형률 곡선의 1/3~1/4 점에서 구하며 클수록 변형이 작다":"탄성계수는 응력-변형률 곡선의 1/3~1/4 지점을 이은 할선탄성계수로 구하며 큰 값일수록 변형이 작습니다.","함수비가 많은 점토질에는 유리하지 않다":"함수비가 높은 점토질 흙에서는 타이어가 빠져 타이어 도저가 유리하지 않습니다.","함수율이 늘면 반발경도가 크게 측정되는 것이 아니라 습윤상태 보정이 필요하다":"함수율이 높아도 반발경도가 크게 나오는 것이 아니라 습윤상태 보정이 필요합니다.","해머 무게 64kg, 낙하높이 76cm이고 30cm 관입 타격수가 N치이다":"SPT는 무게 64kg 해머를 76cm 높이에서 떨어뜨려 30cm 박는 데 필요한 타격수를 N치로 삼습니다.","해머 효율 측정이 필요하고 PDA는 응력분포·경시효과·해머 효율을 파악한다":"동역학적 방법은 해머 효율을 재야 하고, PDA는 응력분포, 경시효과, 해머 효율을 알려 줍니다.","현장 건조단위중량을 실내 최대건조단위중량과 비교해 구한다":"다짐도는 현장에서 잰 건조단위중량을 실내 시험의 최대건조단위중량에 견주어 구합니다.","현장다짐 시 코어절삭법·모래치환법·고무막법이다":"현장 다짐도를 재려면 코어절삭법, 모래치환법, 고무막법으로 흙의 단위중량을 구합니다.","현장밀도·평판재하·다짐·함수량시험이다":"노체 품질시험은 현장밀도, 평판재하, 다짐, 함수량시험으로 합니다.","현장배합 입도·아스팔트 함량·시공관리 목표를 정하며 포장두께는 정하지 않는다":"시험포장은 현장배합 입도, 아스팔트 함량, 시공관리 목표를 정하며 포장두께를 정하는 것은 아닙니다.","현장 부근 자연재료와 일반 토공 중장비를 쓴다":"필댐은 현장 근처의 자연재료와 일반 토공 중장비로 지을 수 있습니다.","현장 원위치 시험으로 점토의 비배수 전단강도를 구한다":"베인전단시험은 현장 원위치 시험으로 점토의 비배수 전단강도를 구합니다.","현장타설말뚝은 동역학적 방법으로 지지력을 추정하지 않는다":"현장타설말뚝의 지지력은 박을 때의 타격으로 추정하는 동역학적 방법을 쓰지 않습니다.","호박돌 등 장애물 제거가 어렵다":"오픈케이슨은 호박돌 같은 장애물을 치우기 어렵습니다.","혼합 기능은 없고, 열에 강하지도 무겁지도 않다":"지오텍스타일에는 혼합 기능이 없고, 열에 강하거나 무겁다고 할 수도 없습니다.","혼화재료는 사용량에 따라 혼화재와 혼화제로 나뉜다":"혼화재료는 사용량이 많은지 적은지에 따라 혼화재와 혼화제로 나눕니다.","화기를 가까이 했을 때 인화되는 최저온도이다":"인화점은 아스팔트에 불을 가까이 댔을 때 증기에 불이 붙는 가장 낮은 온도입니다.","활동면 위의 흙을 연직 평행 절편으로 나누는 방법에는 펠레니우스·비숍 간편법·스펜서가 있다":"절편법은 활동면 위의 흙을 수직 띠로 쪼개 계산하며 펠레니우스, 비숍 간편법, 스펜서 방법이 있습니다.","활동면의 간극수압이 높아지고 바닥면 양압력이 증가한다":"활동면의 간극수압이 높아지고 바닥면에 양압력이 커져 옹벽이 불안정해집니다.","황·목탄·초석의 미분말을 혼합한 것으로 흑회색이다":"흑색화약은 황, 목탄, 초석의 미분말을 섞은 것으로 흑회색을 띱니다.","황산나트륨 포화용액으로 5회 시험하며 잔골재 손실질량은 10% 이하가 표준이다":"시험은 황산나트륨 포화용액에 5회 반복하고, 잔골재의 손실질량 표준 한도는 10%입니다.","황산염 저항성이 늘고 백태가 줄며 건조수축은 감소한다":"고압증기양생은 황산염 저항성을 높이고 백태와 건조수축을 줄입니다.","흐트러진 상태 토량÷자연상태 토량":"L은 흐트러져 부푼 토량을 자연상태 토량과 비교한 토량변화율입니다.","흐트러진 시료용이고 교란된 흙은 압축·전단강도가 작다":"오거보링 시료는 흐트러져 있어 교란된 흙이 되므로 압축·전단강도가 작게 나옵니다.","흑색화약을 심약으로 피복한 것이다":"도화선은 흑색화약을 심약으로 삼아 겉을 감싼 것입니다.","흙댐은 기초가 다소 불량해도 시공할 수 있고 아치댐은 암반이 견고하고 계곡 폭이 좁은 곳에 적합하다":"흙댐은 기초가 조금 나빠도 지을 수 있고, 아치댐은 암반이 단단하고 계곡 폭이 좁은 곳에 맞습니다.","흙의 간극은 서로 연결되어 물이 흐를 수 있고 수두차가 한계동수경사에 이르면 분사가 발생한다":"흙 간극은 서로 이어져 물이 흐르며, 수두차가 한계동수경사에 이르면 분사가 일어납니다.","흙입자와 물의 압축성은 무시하고 물의 이동은 다르시 법칙을 따른다":"흙입자와 물은 압축되지 않고 물은 다르시 법칙을 따라 움직인다고 가정하는 압밀 이론입니다.","흡수율은 3% 이하이고 입자 모양 판정 실적률 55% 이상이어야 한다":"부순골재 흡수율은 3% 이하여야 하고, 모양을 가늠하는 실적률은 55% 이상이어야 합니다.","흡수율이 큰 골재일수록 수축이 크며 습기를 흡수하면 팽창하고 건조하면 수축한다":"흡수율이 큰 골재는 수축이 크고, 콘크리트는 습기를 흡수하면 팽창하고 마르면 수축합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
